import{B as o,a as c,b as r,c as s,d as g,e as l,f as p,g as u,h as d,i as m}from"./reference-bank-001-100-BGW38Zik.js";import{B as y,a as v,b,c as k,d as f,e as w,f as q,g as x,h as P,i as T}from"./reference-bank-101-200-C9-KhFit.js";import{O as S,a as B}from"./original-bank-ClKuypH0.js";import{S as R}from"./index-RMCt7Z8K.js";const A=[...o,...c,...r,...s,...g,...l,...p,...u,...d,...m,...y,...v,...b,...k,...f,...w,...q,...x,...P,...T],C=[{id:"o501",n:501,t:0,origin:"original",eco:"R9",domain:"process",approach:"hybrid",caseId:"c1",tags:["hybrid","eco-2026","format-2026","case","burn-up","forecast"],type:"mc",q:"The project manager reviews the release burn-up chart in the case with the product owner before the next steering committee meeting. The team's velocity has stayed between 17 and 22 points per sprint, and the release scope has grown in each of the last three sprints. Which conclusion is best supported by the chart?",opts:["The release is on track, because completed work has grown in every sprint and the velocity has stayed steady at about 19 points","At the current velocity and scope growth, the remaining release scope will not be complete by the end of sprint 8","Velocity has fallen by half since sprint 2, so the team must add developers before the sprint 8 pilot release","The original 200 points will be complete by sprint 8 if the team simply keeps its current velocity of about 19 points"],ans:[1],why:["Sai: công việc hoàn thành tăng đều chỉ cho biết đội làm ổn định, chưa nói gì về đích. Đường scope cũng đi lên khoảng 15 điểm mỗi sprint, nên khoảng cách tới đích không thu hẹp đủ nhanh.","Đúng: sau sprint 5 còn 245 − 95 = 150 điểm. Ba sprint còn lại với velocity khoảng 19 điểm chỉ thêm chừng 57 điểm, trong khi scope vẫn tăng khoảng 15 điểm mỗi sprint. Biểu đồ cho thấy bản phát hành sẽ không đủ scope vào sprint 8.","Sai: velocity đi từ 22 (sprint 2) xuống 17 (sprint 5), giảm chưa tới một phần tư, không phải một nửa. Thêm người cũng là giải pháp đưa ra trước khi phân tích nguyên nhân thật là scope tăng.","Sai: 200 điểm ban đầu còn thiếu 105 điểm, mà ba sprint ở velocity khoảng 19 chỉ cho gần 57 điểm. Quan trọng hơn, đích thật bây giờ là 245 điểm và vẫn đang tăng, nên 200 điểm không còn là mốc của bản phát hành."],exp:'Task R9 "Evaluate project status": đọc burn-up phải nhìn cả hai đường. Đường hoàn thành cho biết tốc độ; đường scope cho biết đích có dịch chuyển không. Khi đích chạy cùng tốc độ với đội, bản phát hành không bao giờ tới. Quy tắc nhớ: dự báo = phần còn lại ÷ velocity, cộng phần scope dự kiến tăng thêm. Bẫy: kết luận "ổn" chỉ vì đường hoàn thành đi lên đều.'},{id:"o502",n:502,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",caseId:"c1",tags:["hybrid","eco-2026","format-2026","case","expectations","release-scope"],type:"mr",q:"The forecast from the burn-up chart shows that the full release backlog will not be ready for the pilot. The clinic operations director still expects every requested feature to be live at go-live, and the vendor's hardware install dates for the pilot clinics are fixed by contract. Which two actions should the project manager take next? (Choose two.)",opts:["Review the burn-up forecast with the director and the product owner, showing the scope likely to be ready by sprint 8","Work with the product owner and the clinic managers to agree the minimum set of features the three pilot clinics need on day one","Ask the team to commit to about 50 points per sprint so that the full release backlog fits into the three remaining sprints","Ask the vendor to move the pilot install dates later so that the hardware and the full software scope arrive together","Freeze the release backlog at 200 points and reject every new clinic request until the pilot release has gone live"],ans:[0,1],why:["Đúng: kỳ vọng của director dựa trên thông tin cũ. PM đưa dữ liệu dự báo ra một cách minh bạch, cùng product owner, để director thấy phần scope thực tế có thể sẵn sàng. Đây là bước làm rõ kỳ vọng trước mọi quyết định.",'Đúng: thống nhất bộ tính năng tối thiểu mà các phòng khám cần ngày đầu biến một kỳ vọng mơ hồ ("mọi tính năng") thành phạm vi đo được. Product owner giữ quyền ưu tiên backlog, PM tạo điều kiện cho cuộc trao đổi.',"Sai: velocity là dữ liệu đo được, không phải con số ra lệnh. Ép đội cam kết gần gấp ba velocity làm giảm chất lượng và phá niềm tin, mà không giải quyết việc kỳ vọng đang lệch.","Sai: lịch lắp đặt của vendor nằm trong hợp đồng và trong baseline của phần predictive. Dời lịch là một change request có chi phí, và chưa cần khi kỳ vọng về scope còn chưa được làm rõ.","Sai: khóa cứng backlog và từ chối mọi yêu cầu là cực đoan. Yêu cầu mới vẫn có thể có giá trị cao hơn hạng mục cũ; việc đúng là ưu tiên lại cùng product owner, không phải đóng cửa với các phòng khám."],exp:'Task P5 "Align stakeholder expectations": kỳ vọng lệch thì việc đầu tiên là đưa dữ liệu ra và thống nhất lại, không phải ép đội hay đổi kế hoạch của phần predictive. Trong dự án hybrid, phần agile điều chỉnh bằng scope (ưu tiên backlog), còn mốc của phần predictive được giữ ổn định. Bẫy: các phương án "làm nhanh hơn" hoặc "khóa cứng" nghe quyết đoán nhưng bỏ qua người sở hữu kỳ vọng.'},{id:"o503",n:503,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",caseId:"c1",tags:["hybrid","eco-2026","format-2026","case","integrated-plan","pull-down"],type:"dropdown",q:"The project manager writes a short note for the steering committee that explains how the two parts of the rollout are controlled. Select the option that correctly completes each part of the note.",template:"The vendor's install dates and the pilot go-live are controlled through the {0}. The features that the product owner selects for the pilot release are controlled through the {1}. When a sprint review shows that a feature planned for the pilot will slip, the project manager first checks the effect on the {2}.",blanks:[["integrated schedule baseline","release roadmap","risk register","team charter"],["procurement plan","product backlog","scope baseline","issue log"],["team velocity target","vendor contract price","pilot go-live milestone","retrospective actions"]],opts:[],ans:[0,1,2],why:["ngày lắp đặt theo hợp đồng và mốc go-live là phần predictive, nên được quản lý trong integrated schedule baseline. Release roadmap chỉ là hướng đi dự kiến, không giữ ngày cam kết với vendor; risk register và team charter không phải công cụ kiểm soát lịch.","phạm vi của phần agile được quản lý bằng product backlog do product owner ưu tiên. Scope baseline là cách của phần predictive; procurement plan và issue log không quyết định tính năng nào vào bản phát hành.","trong dự án hybrid, điểm nối giữa hai phần là mốc go-live chung. Một tính năng trễ chỉ đáng lo khi nó ảnh hưởng tới mốc đó. Velocity target, giá hợp đồng hay việc retrospective không phải câu hỏi đầu tiên."],exp:'Task R1 "Develop an integrated project management plan and plan delivery": dự án hybrid có hai cơ chế kiểm soát, và PM phải biết điểm nối giữa chúng. Phần predictive giữ baseline (ngày, hợp đồng); phần agile giữ backlog (scope linh hoạt). Khi phần agile thay đổi, câu hỏi đầu tiên là ảnh hưởng tới mốc tích hợp, ví dụ go-live. Bẫy: dùng công cụ của phần này để kiểm soát phần kia.'},{id:"o504",n:504,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","earned-value","forecast"],type:"mc",exhibit:{title:"Cumulative planned value, earned value and actual cost",kind:"line",unit:"$ thousand",columns:["Month","Planned value (PV)","Earned value (EV)","Actual cost (AC)"],rows:[["M1",40,38,42],["M2",90,85,95],["M3",150,135,150],["M4",220,190,215],["M5",300,250,290]],note:"Budget at completion (BAC): $600 thousand. Planned duration: 10 months."},q:"A warehouse fit-out project follows a predictive plan and has just finished month 5 of 10. The project manager is preparing the monthly status report for the sponsor using the earned value chart shown. The cost and schedule variances have grown in every month so far. Which statement correctly describes the project's status?",opts:["Behind schedule and over budget; if cost performance stays the same, the estimate at completion is about $696,000","Behind schedule but under budget, because the actual cost of $290,000 is lower than the planned value of $300,000 so far","Ahead of schedule and over budget, because the actual cost has been higher than the earned value in every month","On schedule and on budget overall, because the month 5 cost and schedule variances are both under 10 percent"],ans:[0],why:["Đúng: SPI = EV ÷ PV = 250 ÷ 300 ≈ 0,83 (chậm tiến độ) và CPI = EV ÷ AC = 250 ÷ 290 ≈ 0,86 (vượt chi phí). Nếu hiệu suất chi phí giữ nguyên, EAC = BAC ÷ CPI = 600 ÷ 0,862 ≈ $696.000.","Sai: so AC với PV là bẫy kinh điển. Ngân sách được đánh giá bằng EV so với AC: làm được $250.000 công việc mà tốn $290.000, tức là vượt chi phí $40.000.","Sai: nửa sau đúng (AC > EV mỗi tháng), nhưng EV luôn thấp hơn PV, tức là chậm tiến độ chứ không phải vượt tiến độ. SV tháng 5 = 250 − 300 = −$50.000.","Sai: SV = −$50.000 tức khoảng −17 % so với PV, và CV = −$40.000 tức khoảng −16 % so với EV. Cả hai đều vượt 10 %, nên không thể gọi là đúng tiến độ và đúng ngân sách."],exp:'Task R6 "Plan and manage finance" (và R9 khi báo cáo): đọc biểu đồ EVM bằng ba đường. EV so với PV cho biết tiến độ; EV so với AC cho biết chi phí; PV so với AC không cho biết gì đáng tin. Quy tắc nhớ: chỉ số nào dưới 1 là xấu, và EAC = BAC ÷ CPI khi hiệu suất được giả định giữ nguyên. Bẫy: "tiêu ít hơn kế hoạch" không có nghĩa là "dưới ngân sách" khi công việc làm được còn ít hơn.'},{id:"o505",n:505,t:0,origin:"original",eco:"B5",domain:"business",approach:"predictive",tags:["predictive","eco-2026","format-2026","matching","risk-response"],type:"match",q:"A project manager is building a four-storey office block under a predictive plan. During a risk workshop, the team agreed one response for each of four threats in the risk register. Match each response the team agreed to the threat response strategy it represents.",items:["Heavy rain could flood the excavation. The earthworks contract is amended so the subcontractor bears the cost of pumping and repairs.","Some welders may produce faulty joints. Every welder must pass a qualification test on site before starting work.","A crane supplier that is new to the company may miss its delivery date. The team switches to a crane from the company's own fleet.","A small permit fee may rise by about 2 percent. The team records the threat and will pay any increase from the contingency reserve."],opts:["Avoid","Transfer","Mitigate","Accept"],ans:[1,2,0,3],why:["Transfer: hậu quả tài chính của rủi ro được chuyển sang bên thứ ba qua điều khoản hợp đồng. Rủi ro vẫn có thể xảy ra, nhưng người chịu chi phí đã đổi.","Mitigate: bài kiểm tra tay nghề làm giảm xác suất mối hàn lỗi. Rủi ro vẫn còn, chỉ nhỏ hơn, nên đây không phải avoid.","Avoid: đổi sang cần cẩu của chính công ty loại bỏ hẳn sự phụ thuộc vào nhà cung cấp mới, nên mối đe dọa không còn tồn tại trong kế hoạch.","Accept (active): mối đe dọa nhỏ, được ghi nhận và có sẵn contingency để dùng khi xảy ra. Không có hành động nào làm thay đổi xác suất hay tác động."],exp:'Task B5 "Plan and manage risk": bốn chiến lược cho threat phân biệt theo việc rủi ro còn hay không và ai chịu. Avoid: đổi kế hoạch để rủi ro biến mất. Transfer: rủi ro còn nhưng bên khác chịu hậu quả. Mitigate: rủi ro còn nhưng nhỏ hơn. Accept: rủi ro còn nguyên, chỉ chuẩn bị tiền hoặc thời gian (active) hoặc không làm gì (passive). Bẫy: nhầm mitigate với avoid khi hành động nghe rất mạnh.'},{id:"o506",n:506,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","point-and-click","critical-path"],type:"hotspot",figure:{title:"Network diagram (finish-to-start, durations in days)",width:640,height:250,boxes:[{label:"Start",x:12,y:100,w:76,h:50},{label:"A",sub:"3 days",x:128,y:30,w:104,h:58},{label:"B",sub:"5 days",x:128,y:162,w:104,h:58},{label:"C",sub:"4 days",x:288,y:30,w:104,h:58},{label:"D",sub:"6 days",x:288,y:162,w:104,h:58},{label:"E",sub:"2 days",x:440,y:96,w:84,h:58},{label:"Finish",x:556,y:100,w:76,h:50}],edges:[[0,1],[0,2],[1,3],[2,4],[3,5],[4,5],[5,6]]},q:"A project manager is tracking a short equipment upgrade with the network diagram shown. Before work starts, the supplier warns that activity C will take 9 days instead of the 4 days in the plan. No other durations or dependencies change. Select the activities that are on the critical path after this change.",opts:[],ans:[1,3,5],why:["Start là mốc, không có thời lượng, nên không được tính là một hoạt động trên đường găng.","Cần chọn: đường A–C–E bây giờ dài 3 + 9 + 2 = 14 ngày, dài hơn B–D–E (13 ngày), nên A nằm trên đường găng mới.","Không chọn: B nằm trên đường B–D–E dài 13 ngày. Trước thay đổi đây là đường găng, nhưng sau khi C kéo dài thì đường này có 1 ngày float.","Cần chọn: C tăng từ 4 lên 9 ngày làm đường A–C–E dài nhất (14 ngày), nên C nằm trên đường găng.","Không chọn: D thuộc đường B–D–E 13 ngày, giờ có 1 ngày float. Đây là bẫy cho người nhớ đường găng cũ.","Cần chọn: E nằm trên cả hai đường, nên luôn thuộc đường găng dù đường nào dài nhất.","Finish là mốc kết thúc, không phải hoạt động, nên không chọn."],exp:'Task R8 "Plan and manage schedule": đường găng là đường dài nhất qua sơ đồ mạng, và nó có thể đổi khi một hoạt động thay đổi thời lượng. Cách làm: cộng thời lượng từng đường (A–C–E và B–D–E), so sánh, chọn đường dài nhất; hoạt động chung của mọi đường (E) luôn nằm trên đường găng. Bẫy: giữ đường găng cũ sau khi dữ liệu đã đổi.'}],j=[{id:"o507",n:507,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",caseId:"c2",tags:["agile","eco-2026","format-2026","case","conflict","working-agreement"],type:"mc",q:"In the case, Linh wants two reviewers on every change, while Marcus wants a single reviewer for changes under 50 lines. They argued again in sprint planning and the other developers have started taking sides. The team's working agreement says nothing about review size, and the team's own board shows that small changes wait three days for a second review. What should the project manager do?",opts:["Let the product owner decide the review rule, as the long waits in review put the sprint 6 release at risk","Request a single review standard from the council's engineering manager and require both developers to follow it","Facilitate a session where the whole team uses the board's waiting times to agree a review rule for its working agreement","Pair Linh with Marcus on the same stories for one sprint and let them build a shared review habit before any rule is set"],ans:[2],why:["Sai: product owner sở hữu thứ tự ưu tiên của backlog, không sở hữu cách làm việc của đội như quy tắc review. Thời gian chờ review là dữ liệu để đội tự quyết, không phải lý do chuyển quyết định cho product owner. Sẽ đúng nếu tranh cãi là về thứ tự các story.","Sai: working agreement là của chính đội và đề bài không nêu chuẩn bắt buộc nào của công ty. Nhờ manager áp một chuẩn từ trên xuống có thể dừng tranh cãi nhưng làm mất cam kết của đội. Sẽ đúng nếu công ty đã có quy định review mà đội phải theo.","Đúng: quy tắc review là cách làm việc của đội nên đội phải tự thống nhất. Dữ liệu từ bảng (ba ngày chờ review thứ hai) giúp Linh và Marcus bàn bằng bằng chứng thay vì quan điểm, và kết quả được ghi vào working agreement để cả đội cùng giữ.","Sai: ghép cặp giúp hai người hiểu nhau hơn nhưng không tạo ra quy tắc mà cả đội đồng ý, trong khi các story vẫn nằm chờ thêm một sprint. Sẽ đúng nếu mâu thuẫn bắt nguồn từ hiểu sai cách làm việc của nhau chứ không phải từ hai quy tắc khác nhau."],exp:'Task P2 "Manage conflicts": tranh cãi về cách làm việc là xung đột trong đội, và PM đóng vai servant leader giúp các bên tự giải quyết bằng đối thoại có dữ liệu thay vì phán xử hay đẩy lên cấp trên. Quy tắc nhớ: tìm lợi ích gốc của từng bên rồi biến kết quả thành một thỏa thuận chung (working agreement) mà cả đội sở hữu. Bẫy: giao quyền quyết định cho người không sở hữu vấn đề (product owner, manager) vì nghe có vẻ nhanh.'},{id:"o508",n:508,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",caseId:"c2",tags:["agile","eco-2026","format-2026","case","self-organization","servant-leadership"],type:"mr",q:"Two sprints later the team has agreed a review rule, but developers still ask the project manager which story to pick up next and who should review it. The daily stand-up has turned into a status report addressed to the project manager. The project manager wants the team to organize its own work. Which two actions should the project manager take? (Choose two.)",opts:["Publish a daily assignment list naming the story and the reviewer for each developer, and answer questions about it each morning","Turn the questions about who takes which story back to the team and let it decide at the board during stand-up","Name Linh as team lead to assign stories and report each developer's progress to the project manager every day","Ask the team to run the stand-up among themselves around the sprint goal while the project manager notes impediments to clear","Have the product owner allocate each task to a developer in sprint planning and answer the team's questions about order of work"],ans:[1,3],why:["Sai: danh sách phân công hằng ngày biến PM thành người ra lệnh, đúng thứ mà đội đang quá phụ thuộc. Đội hỏi PM ai làm gì là dấu hiệu thiếu tự tổ chức, và phân công chi tiết làm vấn đề nặng thêm. Sẽ đúng nếu đội mới lập và cần khung hướng dẫn tạm thời.","Đúng: trả câu hỏi ai nhận story nào về cho đội và để họ quyết định ngay tại bảng là cách PM trao quyền. Đội tự chọn việc thì cam kết với sprint mạnh hơn, còn PM vẫn hỗ trợ bằng việc gỡ vướng.","Sai: chỉ định Linh làm trưởng nhóm là chuyển kiểu chỉ huy từ PM sang một thành viên, đi ngược với đội tự tổ chức nơi quyền quyết định thuộc cả đội. Sẽ đúng nếu chính đội tự chọn một người điều phối luân phiên.","Đúng: stand-up là cuộc họp của đội về mục tiêu sprint, không phải báo cáo cho PM. Khi đội nói với nhau, PM lắng nghe và ghi lại trở ngại để gỡ, đúng vai trò servant leader.","Sai: product owner quyết định giá trị và thứ tự của backlog, không phân việc cho từng developer. Giao việc từng người cho product owner chỉ đổi người chỉ huy và đội vẫn phụ thuộc. Sẽ đúng nếu câu hỏi là về thứ tự ưu tiên của các story."],exp:'Task P3 "Lead the project team": với đội agile trưởng thành dần, PM chuyển từ giao việc sang trao quyền. Servant leader trả quyết định về cho đội, lắng nghe và gỡ trở ngại, thay vì phân công hay chỉ định một người cầm quyền thay mình. Quy tắc nhớ: ai nắm thông tin hằng ngày thì người đó quyết cách làm. Bẫy: chuyển kiểu chỉ huy sang người khác (trưởng nhóm, product owner) và gọi đó là trao quyền.'},{id:"o509",n:509,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",caseId:"c2",tags:["agile","eco-2026","format-2026","case","matching","moscow","prioritization"],type:"match",q:"The product owner and the team classify four backlog items for the first public release at the end of sprint 6, using the MoSCoW scheme. Match each backlog item to the MoSCoW category it belongs in.",items:["Residents cannot renew loans at all without this, and the council's lending policy requires online renewal from the first release.","Room reservation is valuable and many branches ask for it, but staff can take bookings by phone for a few more weeks.","A dark-mode theme that a few users have asked for; nobody depends on it and the release can ship without it.","A reading-badge game for children, agreed with the product owner as out of scope for the first release and parked for a later one."],opts:["Could have","Must have","Won't have (this time)","Should have"],ans:[1,3,0,2],why:["Must have: chính sách cho vay của hội đồng bắt buộc gia hạn trực tuyến ngay từ bản phát hành đầu, nên thiếu tính năng này thì bản phát hành không đạt yêu cầu. Đó là tiêu chí của Must have.","Should have: đặt phòng rất có giá trị và nhiều chi nhánh cần, nhưng nhân viên vẫn nhận đặt chỗ qua điện thoại được nên chưa cản việc phát hành. Quan trọng nhưng có cách tạm thay thế là dấu hiệu của Should have.","Could have: giao diện tối chỉ vài người đề nghị và không ai phụ thuộc vào nó, nên chỉ làm khi còn dư thời gian và ngân sách. Làm hay không không ảnh hưởng giá trị của bản phát hành.","Won't have (this time): trò chơi huy hiệu đọc sách đã được thống nhất với product owner là ngoài phạm vi bản đầu và để dành cho lần sau. Hạng mục không bị bỏ hẳn mà chỉ không nằm trong lần phát hành này."],exp:`Task R3 "Help ensure value-based delivery": MoSCoW xếp backlog theo hậu quả khi thiếu một hạng mục. Must: thiếu thì bản phát hành vô dụng hoặc vi phạm yêu cầu bắt buộc. Should: quan trọng nhưng có cách tạm. Could: mong muốn, làm khi còn dư sức. Won't (this time): đã thống nhất không làm ở lần này. Bẫy: xếp theo mức độ ồn ào của người yêu cầu thay vì theo hậu quả của việc thiếu.`},{id:"o510",n:510,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",caseId:"c3",tags:["predictive","eco-2026","format-2026","case","fixed-price","vendor-performance"],type:"mc",q:"The project manager reviews the table in the case with the trust's clerk of works, who verified the percentage complete on site at the end of month 6. The installation contractor's latest invoices, which are included in the table, are waiting for the project manager's approval. What should the project manager do?",opts:["Approve all four invoices as submitted and leave the cost of recovering late work with the contractor under the fixed price","Raise a change request for extra budget to recover the 20-point delay in electrical distribution and in theatre ventilation","Ask the contractor to bill the two late packages on time and materials and pay only for the hours its crews actually work","Cap the electrical distribution invoice at the verified 50 percent, and ask the contractor for a recovery plan for both late packages"],ans:[3],why:["Sai: giá cố định đúng là chuyển rủi ro chi phí cho nhà thầu, nhưng thanh toán vẫn phải theo công việc đã xác minh. Hóa đơn gói điện tính 1.050 nghìn USD (70 %) trong khi công việc thực tế mới 50 % (750 nghìn USD), tức là tính trước 300 nghìn USD. Sẽ đúng nếu mọi hóa đơn khớp với phần trăm đã xác minh.","Sai: chậm tiến độ do nhà thầu thực hiện là rủi ro của nhà thầu theo hợp đồng giá cố định, không phải thay đổi phạm vi do trust yêu cầu. Change request xin thêm ngân sách chỉ đúng khi trust đổi phạm vi hoặc điều khoản hợp đồng đổi.","Sai: chuyển sang time-and-materials đẩy rủi ro chi phí từ nhà thầu về trust và cần sửa hợp đồng, không phải cách xử lý hiệu suất kém. Sẽ đúng nếu phạm vi ban đầu chưa rõ và hai bên chủ động thỏa thuận lại loại hợp đồng.","Đúng: giá trị đã xác minh của gói điện là 1.500 × 50 % = 750 nghìn USD, trong khi đã xuất hóa đơn 1.500 × 70 % = 1.050 nghìn USD, chênh 300 nghìn USD. Gói thông gió cũng chậm 20 điểm (30 % so với 50 %) nhưng hóa đơn 270 nghìn USD khớp với 900 × 30 %. PM chỉ duyệt phần đã xác minh và yêu cầu kế hoạch phục hồi cho cả hai gói chậm."],exp:'Task R5 "Plan and manage procurement": theo dõi hiệu suất nhà cung cấp là so sánh phần trăm hoàn thành đã xác minh với phần đã xuất hóa đơn và với kế hoạch. Quy tắc nhớ: trả theo công việc đã nghiệm thu; giá cố định không cho phép trả trước tiến độ, và chậm tiến độ của nhà thầu được xử lý bằng kế hoạch phục hồi theo hợp đồng. Bẫy: nghĩ rằng giá cố định nghĩa là cứ duyệt hóa đơn, hoặc dùng change request để trả cho chậm trễ của nhà thầu.'},{id:"o511",n:511,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",caseId:"c3",tags:["predictive","eco-2026","format-2026","case","change-control","design-change"],type:"mr",q:"The clinical director's larger recovery room needs more ductwork and a different electrical layout. The director has asked the contractor's site foreman to start the redesign this week to save time. The project has a change management plan with a change control board. Which two actions should the project manager take? (Choose two.)",opts:["Approve the redesign now on the clinical director's authority as the main user of the wing, and update the drawings afterwards","Log the request as a change request and have the contractor and design team assess its effect on cost, schedule and risk","Pay for the redesign from the $480 thousand risk reserve and let the contractor start without a formal variation order","Take the assessed change request to the change control board for a decision before any redesign work begins","Tell the contractor to absorb the redesign cost within the fixed price and start work on the larger room this week"],ans:[1,3],why:["Sai: giám đốc lâm sàng là người dùng chính nhưng không có thẩm quyền duyệt thay đổi thiết kế; thẩm quyền thuộc change control board theo kế hoạch quản lý thay đổi. Sẽ đúng nếu giám đốc cũng là thành viên có quyền duyệt của ban đó và đã nhận đánh giá tác động.","Đúng: mọi yêu cầu thay đổi phải được ghi lại và đánh giá tác động lên chi phí, tiến độ và rủi ro trước khi quyết định. Nhà thầu và nhóm thiết kế là những người biết khối lượng điện và ống gió bị ảnh hưởng.","Sai: 480 nghìn USD dành cho các rủi ro đã nằm trong risk register, không dành cho thay đổi phạm vi mới, và bắt đầu mà không có variation order là bỏ qua kiểm soát thay đổi. Sẽ đúng nếu thay đổi thiết kế là biện pháp ứng phó cho một rủi ro đã ghi nhận và đã được duyệt.","Đúng: sau khi có đánh giá, change control board mới là nơi quyết định chấp thuận hay từ chối, và công việc thiết kế chỉ bắt đầu sau quyết định đó. Cách này bảo vệ scope baseline và ngân sách.","Sai: giá cố định chỉ áp dụng cho phạm vi đã thỏa thuận; yêu cầu mở rộng của trust nằm ngoài phạm vi nên nhà thầu không phải gánh theo giá cũ. Ép họ làm ngay không qua quy trình dễ gây tranh chấp hợp đồng. Sẽ đúng nếu phần mở rộng đã nằm trong phạm vi hợp đồng ban đầu."],exp:'Task B3 "Manage and control changes": một yêu cầu thay đổi đi theo chuỗi ghi nhận, đánh giá tác động, phê duyệt bởi người có thẩm quyền, rồi mới thực hiện và cập nhật baseline. Quy tắc nhớ: không ai, kể cả khách hàng hay sponsor, được bắt đầu công việc thay đổi trước khi quy trình hoàn tất. Bẫy: hợp thức hóa thay đổi sau khi đã làm, hoặc lấy tiền dự phòng cho rủi ro để trả cho thay đổi phạm vi.'},{id:"o512",n:512,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",caseId:"c3",tags:["predictive","eco-2026","format-2026","case","pull-down","contingency","contract-type"],type:"dropdown",q:"The project manager writes a short note to the trust's finance committee about contract risk and the project reserve. In the case, the installation contractor has asked for a price increase because of copper prices, and the clinical director's recovery-room change is waiting for a decision. Select the option that correctly completes each part of the note.",template:"Because the installation contract is {0}, the extra cost of the copper price rise is paid by the {1}. The $480 thousand that the trust set aside for risks already in the risk register is the {2}, and the project manager can draw on it only through the change control process.",blanks:[["a cost-plus-fee contract","a firm fixed-price contract","a time-and-materials contract","a unit-price contract"],["trust's sponsor","design consultant","installation contractor","project manager"],["contingency reserve","management reserve","project budget","cost baseline"]],opts:[],ans:[1,2,0],why:["hợp đồng giá cố định chốt giá trước nên chi phí vượt do bên thầu chịu. Cost-plus-fee và time-and-materials thì bên mua trả chi phí thực tế, còn unit-price tính theo đơn vị khối lượng nên đồng tăng giá vẫn có thể chuyển sang bên mua.","với giá cố định, phần chi phí tăng do giá đồng thuộc về nhà thầu trừ khi trust đổi phạm vi. Sponsor, tư vấn thiết kế hay PM không phải bên chịu rủi ro giá của hợp đồng này.","khoản dành cho các rủi ro đã nhận diện và nằm trong risk register là contingency reserve, nằm trong cost baseline và PM dùng qua kiểm soát thay đổi. Management reserve dành cho rủi ro chưa biết, còn project budget và cost baseline là các tổng lớn hơn."],exp:'Task R6 "Plan and manage finance": loại hợp đồng quyết định ai gánh rủi ro chi phí. Giá cố định đặt rủi ro vào nhà thầu; cost-plus và time-and-materials đặt vào bên mua. Quy tắc nhớ: contingency reserve cho rủi ro đã biết, nằm trong baseline và do PM dùng qua quy trình; management reserve cho rủi ro chưa biết và do cấp cao hơn quyết. Bẫy: lẫn hai loại dự phòng hoặc cho rằng bên mua luôn trả phần vượt.'},{id:"o513",n:513,t:0,origin:"original",eco:"B2",domain:"business",approach:"hybrid",caseId:"c4",tags:["hybrid","eco-2026","format-2026","case","ai","privacy","data-protection"],type:"mc",q:"The project manager finds out that the historic claims copy in the case, which includes policyholders' names and health notes, sits in a cloud workspace that 20 people can open, including staff from other departments. The privacy officer has not yet reviewed whether the data may be used to train the model. What should the project manager do to protect the project's compliance position?",opts:["Bring in the privacy officer to assess whether the claims data may train the model, and restrict access to named project members","Add a data-breach risk to the risk register, name the head of data science as its owner and review it at each sprint review","Have the data science team run bias and accuracy tests on the model before the regulator reviews any claims decisions","Ask the cloud provider to certify the workspace's security and keep the full extract available for faster experiments"],ans:[0],why:["Đúng: dữ liệu có họ tên và ghi chú sức khỏe đang nằm ở nơi 20 người truy cập, gồm cả người ngoài dự án, và chưa ai kiểm tra quyền dùng dữ liệu để huấn luyện mô hình. Đây là vấn đề đã hiện hữu: cần privacy officer đánh giá và thu hẹp quyền truy cập ngay.","Sai: đưa vào risk register là cách xử lý rủi ro có thể xảy ra, còn việc dữ liệu nhạy cảm đang bị mở rộng cho nhiều người là issue đã xảy ra cần hành động ngay. Sẽ đúng nếu dữ liệu đã được bảo vệ và chỉ còn nguy cơ lộ trong tương lai.","Sai: kiểm thử thiên lệch và độ chính xác cần cho độ công bằng của mô hình nhưng không giải quyết việc dữ liệu cá nhân đang được lưu và dùng khi chưa được duyệt. Sẽ đúng nếu câu hỏi là về nghi ngờ mô hình đối xử không công bằng.","Sai: cloud provider chứng nhận an ninh hạ tầng không thay thế việc xác định có được dùng dữ liệu hay không, và giữ nguyên bản sao đầy đủ khiến việc lộ dữ liệu tiếp diễn. Sẽ đúng nếu mối lo là độ an toàn của chính nền tảng lưu trữ."],exp:'Task B2 "Plan and manage project compliance": với dự án AI dùng dữ liệu khách hàng, tuân thủ bảo vệ dữ liệu phải được xác nhận trước khi dùng, không phải sau khi mô hình đã chạy. Quy tắc nhớ: người có chuyên môn pháp lý (privacy officer) xác định điều kiện dùng dữ liệu, PM giới hạn phơi nhiễm và giữ bằng chứng. Bẫy: coi vấn đề đã xảy ra như một rủi ro tương lai, hoặc thay việc kiểm tra quyền dùng dữ liệu bằng các biện pháp kỹ thuật khác.'},{id:"o514",n:514,t:0,origin:"original",eco:"B8",domain:"business",approach:"hybrid",caseId:"c4",tags:["hybrid","eco-2026","format-2026","case","ai","regulation","external-change"],type:"mr",q:"In month 5 the national regulator announces a rule that applies in four months: any automated decision to settle or refuse a claim must be explainable to the policyholder, and a person must be able to review a refusal on request. The tool goes live at the end of month 9, and the fast-track path currently settles claims with no human review. Which two actions should the project manager take? (Choose two.)",opts:["Move the go-live forward by three months to have the tool in service before the new rule takes effect","Replace the AI model with a fixed rule-based scoring engine, which avoids any need to explain automated decisions to policyholders","Confirm with legal counsel and the privacy officer what the rule requires of the claims tool and from which date","Have the product owner rank backlog items for explanations and human review of refusals, then update plan and risks","Propose a separate compliance project to the steering committee that starts after the first regional go-live"],ans:[2,3],why:["Sai: kéo go-live sớm ba tháng không giúp thoát nghĩa vụ vì công cụ vẫn phải tuân thủ ngay khi quy tắc có hiệu lực, và rút ngắn lịch làm tăng rủi ro chất lượng. Sẽ đúng nếu công cụ có thể phát hành sớm mà vẫn đủ chất lượng và quy tắc không áp dụng cho hệ thống đã vận hành.","Sai: thay mô hình bằng bộ luật cố định bỏ đi giá trị của AI mà chưa đánh giá xem quy tắc thực sự đòi hỏi gì. Thay đổi quá lớn khi chưa phân tích. Sẽ đúng nếu pháp chế xác nhận rằng mô hình hiện tại không thể giải thích được.","Đúng: bước đầu khi môi trường bên ngoài đổi là hiểu chính xác yêu cầu và ngày áp dụng cùng pháp chế và privacy officer, thay vì suy đoán. Việc này cho dữ liệu đáng tin để đánh giá ảnh hưởng.","Đúng: sau khi hiểu yêu cầu, product owner xếp ưu tiên lại backlog cho phần giải thích và rà soát của con người, còn PM cập nhật kế hoạch tích hợp và risk register để bảo vệ ngày go-live.","Sai: dự án tuân thủ tách riêng sau go-live nghĩa là công cụ chạy ngay lúc quy tắc có hiệu lực mà chưa tuân thủ. Sẽ đúng nếu quy tắc chỉ bắt đầu áp dụng nhiều tháng sau khi hệ thống đã vận hành."],exp:'Task B8 "Evaluate external business environment changes": khi quy định mới xuất hiện, PM làm hai việc theo thứ tự: hiểu đúng yêu cầu và thời hạn cùng người có chuyên môn, rồi đưa tác động vào backlog, kế hoạch và rủi ro. Dự án hybrid điều chỉnh phần agile bằng backlog và bảo vệ mốc tích hợp của phần predictive. Bẫy: các phương án dời mốc, đổi công nghệ hoặc tách dự án nghe quyết đoán nhưng bỏ qua bước phân tích.'},{id:"o515",n:515,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",caseId:"c4",tags:["hybrid","eco-2026","format-2026","case","matching","communication","ai"],type:"match",q:"The project manager updates the communication plan for the quarter before go-live. In the case, each stakeholder group needs a different message in a different form. Match each stakeholder to the communication method that best fits what that stakeholder needs.",items:["The chief executive wants to know within two minutes whether the programme will reach go-live on time.","Claims adjusters must try the tool's explanations on real claims and say whether they trust them before the tool is used in their region.","The data protection regulator expects evidence of how personal data is handled in the project.","The platform engineering team in another city depends on fixed dates for interface delivery."],opts:["Sprint demo with feedback","Formal written compliance report","Weekly dependency meeting","One-page status dashboard"],ans:[3,0,1,2],why:["One-page status dashboard: tổng giám đốc cần biết trong hai phút chương trình có kịp go-live không. Một trang mốc và rủi ro đáp ứng đúng nhu cầu đó, còn báo cáo dài sẽ không được đọc.","Sprint demo with feedback: điều chỉnh viên phải tự thử phần giải thích trên hồ sơ thật rồi nói họ có tin không, và phản hồi đó định hướng sprint kế tiếp. Tài liệu viết hay báo cáo tóm tắt không cho họ cơ hội thử.","Formal written compliance report: cơ quan quản lý cần bằng chứng bằng văn bản, có thể lưu và kiểm tra về cách xử lý dữ liệu cá nhân. Một buổi họp hay demo không thay được hồ sơ chính thức.","Weekly dependency meeting: đội nền tảng ở thành phố khác phụ thuộc vào ngày giao interface cố định. Họp hằng tuần với nhật ký phụ thuộc giúp phát hiện sớm các trễ hạn của phần predictive."],exp:'Task P8 "Plan and manage communication": thông điệp và kênh phải theo nhu cầu của từng stakeholder: ai cần biết gì, ở mức chi tiết nào, bằng hình thức nào, bao lâu một lần. Lãnh đạo cần tóm tắt một trang, người dùng cần trải nghiệm trực tiếp, cơ quan quản lý cần hồ sơ chính thức, đội phụ thuộc cần nhịp họp đều. Bẫy: gửi cùng một báo cáo cho tất cả mọi người.'},{id:"o516",n:516,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",caseId:"c5",tags:["agile","eco-2026","format-2026","case","kanban","flow-metrics","cycle-time"],type:"mc",q:"The head of IT service asks the project manager what the chart in the case says about the team's flow. A developer on the service desk argues that the team is working as hard as ever, so nothing has changed. Which conclusion does the chart support?",opts:["The team has become slower at finishing work, so its capacity has fallen and more staff should be added to the service desk","Cycle time is still close to the target, because the number of items finished each week has hardly changed","More items are now open at the same time, because the same weekly throughput takes far longer for each item","The WIP limits are working, as steady throughput shows that the team keeps to them and only the target needs review"],ans:[2],why:["Sai: throughput vẫn là 10 mục mỗi tuần, nên năng lực hoàn thành của đội gần như không đổi; thêm người không giải quyết việc mỗi mục nằm lâu hơn. Sẽ đúng nếu throughput giảm trong khi cycle time tăng.","Sai: mục tiêu là 8 ngày, nhưng từ tuần 5 cycle time là 9, 10, 11 rồi 12 ngày, vượt mục tiêu một nửa. Throughput ổn định không có nghĩa thời gian xử lý ổn định.","Đúng: theo Little's Law, số mục đang làm ≈ throughput × cycle time. 10 mục mỗi tuần là 2 mục mỗi ngày: tuần 1 có 2 × 6 = 12 mục đang làm, đúng bằng tổng giới hạn WIP; tuần 8 có 2 × 12 = 24 mục, gấp đôi. Việc ùn lại dù đội xong số mục như cũ.","Sai: tổng giới hạn WIP là 12 mục, nhưng tuần 8 trung bình có khoảng 24 mục đang làm, nên giới hạn đã bị vượt chứ không được giữ. Sẽ đúng nếu cycle time giữ quanh 6 ngày."],exp:`Task R9 "Evaluate project status": với Kanban, đọc cycle time và throughput cùng nhau. Little's Law cho biết WIP trung bình ≈ throughput × cycle time, nên khi throughput phẳng mà cycle time tăng thì lượng việc dở dang tăng, tức là giới hạn WIP không còn được giữ. Bẫy: coi đội bận như cũ là dòng chảy không đổi, hoặc xin thêm người khi vấn đề là quá nhiều việc cùng lúc.`},{id:"o517",n:517,t:0,origin:"original",eco:"B4",domain:"business",approach:"agile",caseId:"c5",tags:["agile","eco-2026","format-2026","case","point-and-click","kanban","wip-limit","impediments"],type:"hotspot",figure:{title:"Service desk board on Monday of week 9 (current WIP against the agreed limit)",width:720,height:190,boxes:[{label:"Analysis",sub:"WIP 3 / limit 3",x:20,y:60,w:120,h:80},{label:"In progress",sub:"WIP 9 / limit 4",x:160,y:60,w:120,h:80},{label:"User reply",sub:"WIP 6 / limit 3",x:300,y:60,w:120,h:80},{label:"Testing",sub:"WIP 1 / limit 2",x:440,y:60,w:120,h:80},{label:"Done",sub:"10 this week",x:580,y:60,w:120,h:80}],edges:[[0,1],[1,2],[2,3],[3,4]],labels:[{text:"Work moves from left to right",x:360,y:32,anchor:"middle"}]},q:"The project manager prepares the daily meeting for the service desk team in the case, using the board shown. Cycle-time data shows that items in In progress move on within two days, while items in User reply wait an average of eight days for customers, and developers pull new tickets whenever one is stuck there. Select the one column where the team should act first to restore the flow.",opts:[],ans:[2],why:["Không chọn: Analysis có 3 mục với giới hạn 3, đúng bằng giới hạn và các mục vẫn di chuyển. Cột này không phải điểm tắc.","Không chọn: In progress vượt giới hạn nhiều nhất (9 so với 4), nhưng các mục ở đây đi tiếp trong hai ngày. Cột này đầy vì đội nhận thêm việc khi ticket bị kẹt ở User reply, nên nó là hệ quả chứ không phải nguyên nhân.","Cần chọn: User reply là ràng buộc thật. Ticket chờ khách trung bình tám ngày, chiếm chỗ (6 so với 3) và khiến developer kéo thêm việc mới. Dồn sức xử lý cột này (gọi lại khách, đặt hạn trả lời, đóng ticket cũ) mới khôi phục được dòng chảy.","Không chọn: Testing có 1 mục với giới hạn 2, đang thiếu việc vì ùn ở phía trước. Đó là hệ quả của điểm tắc, không phải điểm tắc.","Không chọn: cột Done không có giới hạn WIP, và 10 mục xong trong tuần chỉ cho biết throughput, không phải điểm tắc."],exp:'Task B4 "Remove impediments and manage issues": khi nhiều cột cùng quá tải, PM không chọn cột có con số lớn nhất mà tìm ràng buộc thật (constraint), tức là chỗ công việc kẹt vì chờ bên ngoài và khiến các cột khác phình ra. Cách làm: so sánh thời gian chờ ở từng cột với dòng chảy, rồi dồn sức (swarm) vào cột đó trước. Bẫy: chữa triệu chứng ở cột vượt giới hạn nhiều nhất hoặc cột trống, trong khi nguyên nhân nằm ở cột chờ khách.'},{id:"o518",n:518,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",caseId:"c5",tags:["agile","eco-2026","format-2026","case","wip-limit","team-leadership","kanban"],type:"mc",q:"At the retrospective in the case, the team has exceeded the WIP limits in two columns for three weeks. Developers explain that they start new tickets whenever a ticket is waiting for a user's reply, because idle time looks bad on the head of IT service's Friday utilisation report. What should the project manager do?",opts:["Remove the WIP limits on the two columns and track the number of open items there until user replies come back much faster than today","Agree with the head of IT service to swap the utilisation report for a flow report, and help the team set a blocked-ticket rule","Appoint one team member to check the board every morning and stop anyone who pulls a new ticket above a limit","Raise the WIP limits in the two columns to match today's counts so that the board shows the real work in progress"],ans:[1],why:["Sai: bỏ giới hạn WIP xóa luôn công cụ giúp lộ ra điểm tắc, trong khi nguyên nhân thật vẫn còn. Sẽ đúng nếu giới hạn ban đầu đặt sai và cả đội đã đánh giá lại bằng dữ liệu.","Đúng: nguyên nhân gốc là báo cáo utilisation thưởng cho việc luôn bận, nên đội bắt đầu việc mới thay vì xử lý ticket đang chờ. Đổi sang báo cáo dòng chảy cùng head of IT service và giúp đội đặt quy tắc cho ticket bị chặn giải quyết đúng động lực.","Sai: cử một người canh bảng chỉ xử lý hành vi bề mặt và biến một thành viên thành cảnh sát, trong khi động lực đo lường vẫn đẩy đội phá giới hạn. Sẽ đúng nếu nguyên nhân là đội chưa quen với quy tắc mới và chưa có áp lực nào khác.","Sai: nâng giới hạn theo số đếm hiện tại hợp thức hóa tình trạng quá tải và làm mất tác dụng của WIP limit. Sẽ đúng nếu dữ liệu cho thấy đội xử lý ổn định ở mức WIP cao hơn mà cycle time không tăng."],exp:'Task P3 "Lead the project team": khi đội liên tục phá một quy tắc, hỏi vì sao trước. Ở đây hệ thống đo lường (báo cáo utilisation) khiến việc bắt đầu thêm ticket có vẻ hợp lý, nên PM phải đổi động lực cùng người đặt ra nó rồi giúp đội đồng ý một quy tắc cho ticket bị chặn. Bẫy: xử lý hành vi bằng kiểm soát hoặc sửa giới hạn trong khi nguyên nhân là cách đo.'},{id:"o519",n:519,t:0,origin:"original",eco:"R10",domain:"process",approach:"predictive",caseId:"c6",tags:["predictive","eco-2026","format-2026","case","sustainability","closure","handover"],type:"mc",q:"Acceptance tests have passed at 11 schools in the case, and the school 12 test is scheduled for next week. The sponsor wants to close the project on Friday to release the budget. The operations manual is drafted, but the facilities team has not yet received the as-built drawings or the inverter warranty certificates, and the sponsor has not signed the acceptance. What should the project manager do?",opts:["Close the project on Friday and ask the facilities team to collect the remaining documents from the contractor as part of its normal work after closure","Move the open handover items into a follow-up project with its own budget and close this project before the fiscal year ends","Release the contractor's final payment once the school 12 test passes, then archive the handover documents in the project folder","Hand over the drawings, warranty certificates and manual to the facilities team and obtain the sponsor's signed acceptance before closing"],ans:[3],why:["Sai: đóng dự án khi tài liệu bàn giao còn thiếu đẩy việc chưa xong sang đội vận hành và để họ vận hành mà không có bản vẽ hoàn công hay bảo hành. Sẽ đúng nếu các tài liệu đó đã được bàn giao và chỉ còn thủ tục hành chính.","Sai: chuyển phần bàn giao dở sang dự án khác chỉ để kịp năm tài chính là trì hoãn việc đóng thật sự và tạo thêm thủ tục. Sẽ đúng nếu sponsor và các bên đã đồng ý bằng văn bản rằng phạm vi bàn giao được tách riêng.","Sai: khoản thanh toán cuối của nhà thầu gắn với chữ ký nghiệm thu của sponsor, nên không thể trả khi chỉ có kết quả test. Lưu tài liệu vào thư mục dự án cũng không phải là bàn giao cho đội vận hành.","Đúng: đóng dự án đòi hỏi bàn giao đầy đủ sản phẩm và tài liệu (hướng dẫn vận hành, bản vẽ hoàn công, chứng nhận bảo hành) cho đội vận hành, cùng nghiệm thu chính thức của sponsor. Chỉ khi đó mới đóng được dự án và điều kiện thanh toán cuối được thỏa."],exp:'Task R10 "Manage project closure": đóng dự án là khi sản phẩm đã được chấp thuận chính thức và đã bàn giao đủ cho đội vận hành, không phải khi hết hạn ngân sách. Quy tắc nhớ: nghiệm thu, bàn giao tài liệu, đóng hợp đồng, rồi mới đóng dự án. Bẫy: đóng sớm vì áp lực của sponsor và để vấn đề rơi sang đội vận hành.'},{id:"o520",n:520,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",caseId:"c6",tags:["predictive","eco-2026","format-2026","case","sustainability","knowledge-transfer"],type:"mr",q:"The contractor's lead installer holds most of the practical knowledge about the inverter settings and roof-access limits of the 12 buildings, and her crew leaves in three weeks. Two of the four district technicians have never worked on solar inverters, and district rules forbid support contracts after the project closes, so the facilities team must run the systems alone. Which two actions best ensure this? (Choose two.)",opts:["Email the contractor's design drawings and equipment manuals to all four technicians and ask them to study these before the crew leaves","Schedule hands-on sessions at two schools where the four technicians run inverter checks while the lead installer watches and corrects them","Keep the lead installer on call under a one-year support contract and route all fault questions from the technicians to her","Have the lead installer write inverter settings, roof-access rules and fault steps into a guide that the technicians test live","Ask the two technicians who know solar inverters to train the other two after the project closes and the crew has left"],ans:[1,3],why:["Sai: gửi tài liệu cho bốn kỹ thuật viên chuyển thông tin chứ chưa chuyển được kỹ năng, và không ai kiểm tra họ đã hiểu chưa. Sẽ đúng nếu tài liệu chỉ là phần bổ sung cho buổi thực hành đã có.","Đúng: thực hành trực tiếp với người có kinh nghiệm đứng cạnh sửa lỗi chuyển được tri thức ngầm như cài đặt biến tần và hạn chế khi lên mái. Kỹ thuật viên làm thật và được kiểm chứng trước khi đội nhà thầu rời đi.","Sai: quy định của district không cho hợp đồng hỗ trợ sau khi đóng dự án, và đội phải tự vận hành. Giữ người lắp đặt trên đường dây một năm cũng chỉ tạo phụ thuộc vào người ngoài thay vì chuyển tri thức. Sẽ đúng nếu không có quy định cấm và đây chỉ là lớp bổ sung cho các lỗi hiếm.","Đúng: hướng dẫn viết bởi người nắm kiến thức và được kỹ thuật viên chạy thử trên hệ thống thật lưu lại tri thức ở dạng dùng được sau khi đội nhà thầu rời đi, và lộ ra chỗ còn thiếu khi người viết vẫn ở đây.","Sai: hai kỹ thuật viên chưa có kinh nghiệm với biến tần cũng chưa nắm các điều kiện từng mái nên không thể truyền lại, và việc đào tạo sau khi nhà thầu rời đi mất cơ hội hỏi người hiểu rõ nhất. Sẽ đúng nếu họ đã được đào tạo bởi người lắp đặt trước đó."],exp:'Task P7 "Help ensure knowledge transfer": tri thức ngầm chỉ chuyển được khi người nhận thực hành dưới sự quan sát và có tài liệu mà họ đã thử. Hai việc cần làm trước khi người nắm kiến thức rời đi: học bằng làm với người có kinh nghiệm và ghi lại thành hướng dẫn được kiểm chứng. Bẫy: gửi tài liệu rồi coi như đã chuyển giao, hoặc để sau khi dự án đóng mới lo.'},{id:"o521",n:521,t:0,origin:"original",eco:"B6",domain:"business",approach:"predictive",caseId:"c6",tags:["predictive","eco-2026","format-2026","case","pull-down","sustainability","lessons-learned"],type:"dropdown",q:"At closure, the project manager prepares the lessons learned for the school-roof solar project in the case. One lesson is that recycling the old roofing material cost less when the waste hauler was named in the tender documents, which helped the district meet its waste and recycling policy. Select the option that correctly completes each part of the closure note.",template:"The team keeps a lessons learned register during the project and, when the project closes, hands the final version to the group that keeps the district's repository for later projects, the {0}. The lesson about naming the waste hauler in the tender documents is useful to later projects, so the district stores it in its {1}. Changing the district's standard tender template to name the waste hauler is then an update to the {2}.",blanks:[["facilities team","school principals","project management office","installation contractor"],["project management plan","lessons learned repository","stakeholder register","scope baseline"],["enterprise environmental factors","procurement management plan","project charter","organizational process assets"]],opts:[],ans:[2,1,3],why:["case nói project management office giữ repository bài học và mẫu dự án của district, nên bản cuối của register được giao cho PMO khi đóng dự án. Đội vận hành, hiệu trưởng hay nhà thầu không giữ kho tri thức dùng chung cho các dự án sau.","bài học dùng cho các dự án sau được lưu trong lessons learned repository của tổ chức. Project management plan, stakeholder register và scope baseline là tài liệu của riêng dự án này nên không giúp các dự án khác tìm lại bài học.","mẫu hồ sơ mời thầu chuẩn của district là một phần của organizational process assets (quy trình, mẫu biểu, kho kiến thức của chính tổ chức). Enterprise environmental factors là điều kiện bên ngoài hoặc ngoài tầm kiểm soát của đội, còn procurement management plan và project charter chỉ thuộc một dự án."],exp:'Task B6 "Continuous improvement": bài học chỉ có giá trị khi chảy vào tài sản của tổ chức. Chuỗi cần nhớ: ghi bài học trong dự án, giao bản cuối cho nơi quản lý tri thức (PMO), lưu trong repository, rồi đổi quy trình hoặc mẫu biểu, tức là cập nhật organizational process assets. Một bài học về tái chế vật liệu mái nhà cũng đi theo đúng đường này. Bẫy: ghi bài học vào kế hoạch của dự án đã đóng nơi không ai đọc lại.'}],M=[{id:"o522",n:522,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","earned-value","schedule-trend"],type:"mc",exhibit:{title:"Cumulative planned value and earned value",kind:"line",unit:"$ thousand",columns:["Month","Planned value (PV)","Earned value (EV)"],rows:[["M1",30,30],["M2",70,66],["M3",120,108],["M4",180,153],["M5",250,200]],note:"Budget at completion (BAC): $480 thousand. Planned duration: 8 months. Schedule tolerance agreed with the sponsor: SPI not below 0.90."},q:"A data-centre cabling project follows a predictive plan and has just finished month 5 of 8. The project manager is preparing the schedule section of the report for the sponsor from the earned value chart shown. No scope changes have been approved since the baseline. Which statement and action are best supported by the chart?",opts:["The slippage is growing every month, with SPI down from 0.94 to 0.80; analyse the activities behind it and prepare compression options for the sponsor","The $50,000 shortfall in earned value is normal variation within the agreed tolerance, so the baseline stays as it is and the project is reported on schedule","Earned value below planned value shows that less money was spent than planned, so the unused budget can be offered back to the sponsor at the next review","The gap should be closed by a change request that lowers planned value to the $200,000 of earned value achieved, so that the baseline matches the real position"],ans:[0],why:["Đúng: SPI = EV ÷ PV: tháng 2 là 66 ÷ 70 ≈ 0,94; tháng 3 là 108 ÷ 120 = 0,90; tháng 4 là 153 ÷ 180 = 0,85; tháng 5 là 200 ÷ 250 = 0,80. SPI giảm đều và đã dưới ngưỡng 0,90, nên phải phân tích các hoạt động gây trễ và chuẩn bị phương án rút ngắn (crashing, fast tracking). Dự báo thô: 8 ÷ 0,80 = 10 tháng nếu hiệu suất không đổi.","Sai: SV tháng 5 = 200 − 250 = −$50.000 và SPI = 0,80, thấp hơn ngưỡng 0,90 đã thỏa thuận với sponsor. Xu hướng giảm liên tiếp không phải dao động bình thường, nên không thể báo cáo là đúng tiến độ. Sẽ đúng nếu SPI vẫn từ 0,90 trở lên.","Sai: EV thấp hơn PV nghĩa là làm được ít công việc hơn kế hoạch, không liên quan đến số tiền đã chi. Biểu đồ này không có đường AC, nên không kết luận được gì về chi phí hay tiền dư.","Sai: chỉ đặt lại baseline khi có thay đổi phạm vi hoặc điều kiện được duyệt. Ở đây không có thay đổi nào được duyệt, nên hạ PV cho bằng EV chỉ che độ trễ thay vì xử lý nó."],exp:'Task R8 "Plan and manage schedule": xu hướng của SPI quan trọng hơn một con số riêng lẻ; SPI giảm liên tiếp và nằm dưới ngưỡng đã thỏa thuận là tín hiệu phải phân tích nguyên nhân rồi đưa phương án (crashing, fast tracking) cho sponsor. Quy tắc nhớ: SPI = EV ÷ PV, dưới 1 là chậm; dự báo thô thời gian = thời lượng kế hoạch ÷ SPI. Bẫy: đọc EV thấp hơn PV thành "chi ít hơn" hoặc đặt lại baseline để làm đẹp số liệu.'},{id:"o523",n:523,t:0,origin:"original",eco:"R6",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","graphic","contingency","budget-forecast"],type:"mc",exhibit:{title:"Quarterly budget, actual cost and contingency drawn",kind:"bar",unit:"$ thousand",columns:["Quarter","Budget","Actual cost","Contingency drawn"],rows:[["Q1",150,150,0],["Q2",200,215,15],["Q3",250,280,30],["Q4",250,300,50]],note:"Budget for Q1–Q6: $1,000 thousand in total; Q5 and Q6 together are budgeted at $150 thousand. Contingency reserve: $120 thousand. Management reserve is held by the sponsor."},q:"A hybrid programme to replace a hospital scheduling system has completed four of its six quarters. The in-house team has overrun its budget in each recent quarter, and the project manager, who may draw only on the contingency reserve, is preparing the finance update for next week's sponsor review. Based on the chart, what should the project manager do?",opts:["Draw the remaining $25,000 of contingency in quarter 5 and approach the sponsor for more only when the reserve has been used up","Ask the supplier of the scheduling software to absorb the quarter 4 overrun under the terms of its fixed-price agreement with the hospital, as agreed in the contract","Update the estimate at completion from the overrun trend and ask the sponsor to release management reserve before the contingency runs out","Tell the team to gain 20 percent efficiency in quarters 5 and 6 so that the work returns to its budget without any further funding"],ans:[2],why:["Sai: chỉ còn $25.000 contingency (120 − 95) trong khi mức vượt chi tăng 15 → 30 → 50 mỗi quý. Rút nốt cho quý 5 rồi mới xin thêm là phản ứng chậm: khi dự phòng cạn thì không còn thời gian để sponsor ra quyết định.","Sai: công việc do đội nội bộ làm, nên không có nhà cung cấp nào để đòi gánh phần vượt chi. Sẽ đúng nếu đây là hợp đồng fixed price với bên ngoài và nguyên nhân vượt chi nằm ở phía họ.","Đúng: quý 4 vượt 50 trên 250, tức 20 %. Áp tỷ lệ này cho 150 ngân sách quý 5–6: EAC = 945 + 150 × 1,2 = 1.125, vượt ngân sách 1.000 là 125, lớn hơn cả 120 contingency (và xu hướng vẫn đi lên). Chỉ sponsor được mở management reserve, nên PM phải cập nhật dự báo và đề nghị sớm.","Sai: ra lệnh tăng 20 % hiệu suất khi chưa tìm nguyên nhân vượt chi chỉ là một mệnh lệnh, không phải kế hoạch. Dự báo vẫn vượt dự phòng nếu nguyên nhân gốc (ví dụ ước tính thấp) không được xử lý."],exp:'Task R6 "Plan and manage finance": contingency và management reserve có người dùng khác nhau; PM dùng được contingency nằm trong baseline, còn management reserve do sponsor quyết định. Quy tắc nhớ: dự báo EAC từ xu hướng thực tế (actual đã chi cộng phần còn lại theo hiệu suất gần nhất) và báo sponsor trước khi dự phòng cạn. Bẫy: rút nốt contingency rồi mới báo, hoặc đẩy trách nhiệm cho bên không liên quan.'},{id:"o524",n:524,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["agile","eco-2026","format-2026","graphic","burndown","flow"],type:"mc",exhibit:{title:"Sprint burndown, remaining story points",kind:"line",unit:"story points",columns:["Day","Ideal","Actual remaining"],rows:[["Day 0",50,50],["Day 2",40,50],["Day 4",30,48],["Day 6",20,44],["Day 8",10,15],["Day 10",0,0]],note:"Sprint length: 10 working days. Committed scope: 50 story points."},q:"At the end of a 10-day sprint, a product team's burndown looks like the chart shown. The team finished all 50 committed points, the sprint backlog was not changed after planning, and the board is updated automatically each night. The Scrum Master asks the project manager what the shape of the chart says about the way the team worked. What is the best interpretation?",opts:["The team under-committed because it finished everything, so it should pull more stories into the next sprint to use its full capacity and raise its velocity","Stories were opened together and closed at the end, so the team should slice stories smaller and limit work in progress each day","Scope was added early in the sprint, so the project manager should ask the product owner to stop changing the sprint backlog after planning","The board was updated late, so the team should be reminded to record task progress every day before the daily stand-up meeting"],ans:[1],why:["Sai: hoàn thành đủ 50 điểm không có nghĩa là đội cam kết thấp; hình dạng cho thấy công việc dồn vào hai ngày cuối (44 → 15 → 0). Thêm story vào sprint sau chỉ làm rủi ro dồn cuối sprint lớn hơn. Sẽ đúng nếu đường thực tế bám sát đường lý tưởng và kết thúc sớm.","Đúng: đường thực tế gần như phẳng (50 → 44 trong 6 ngày) rồi rơi mạnh (44 → 15 trong 2 ngày), nghĩa là nhiều story được mở song song và chỉ xong cùng lúc ở cuối. Cách xử lý là cắt story nhỏ hơn và giới hạn WIP để có story done đều mỗi ngày.","Sai: đề nói sprint backlog không đổi sau planning, nên đoạn phẳng đầu sprint không phải do thêm scope. Sẽ đúng nếu đường thực tế đi lên (tổng điểm còn lại tăng) ở đầu sprint.","Sai: bảng được cập nhật tự động mỗi đêm nên dữ liệu đáng tin; nhắc cập nhật không giải thích được vì sao việc xong dồn vào cuối. Sẽ đúng nếu bảng cập nhật thủ công và có ngày không ai ghi."],exp:'Task R9 "Evaluate project status": burndown phản ánh cách đội làm việc chứ không chỉ tiến độ. Đường phẳng rồi rơi dốc là dấu hiệu công việc dồn cuối sprint: story quá lớn, nhiều việc dở dang và kiểm thử muộn. Quy tắc nhớ: đường mượt gần đường lý tưởng là dòng giá trị đều; đường bậc thang cần story nhỏ hơn và WIP thấp hơn. Bẫy: kết luận "đội cam kết thấp" chỉ vì đạt 50 trên 50.'},{id:"o525",n:525,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","resource-histogram","resource-smoothing"],type:"mc",exhibit:{title:"Weekly hours demanded from the electrical crew",kind:"bar",unit:"hours per week",columns:["Week","Planned hours"],rows:[["W1",120],["W2",150],["W3",200],["W4",210],["W5",140],["W6",90],["W7",100],["W8",80]],note:"Crew capacity: 160 hours per week. The non-critical activities scheduled in weeks 3 and 4 have 4 weeks of total float."},q:"A hospital wing fit-out follows a predictive plan, and the electrical crew's workload for the next eight weeks is shown in the resource histogram. The contract finish date carries liquidated damages and cannot move, and the sponsor will not fund extra crew. Which action best resolves the over-allocation?",opts:["Level the resources by delaying the activities in weeks 3 and 4 until the crew has spare capacity, then tell the client the new finish date and the reason for the delay","Request two extra electricians from the staffing agency for weeks 3 and 4 so that the crew can work the hours as planned in the schedule","Move the 90 excess hours of non-critical work into week 5, the nearest week, so that the work stays close to its original dates","Smooth the histogram by moving the 90 excess hours of non-critical work into weeks 6 to 8, within its float, so the finish date holds"],ans:[3],why:["Sai: levelling bằng cách lùi các hoạt động tuần 3–4 sẽ đổi ngày kết thúc, mà hợp đồng có phạt (liquidated damages) và ngày không được dời. Sẽ đúng nếu ngày kết thúc còn linh hoạt.","Sai: sponsor không cấp tiền cho thêm thợ, và biểu đồ còn công suất rảnh ở các tuần sau nên thuê thêm người là giải pháp tốn kém không cần thiết. Sẽ đúng nếu việc tuần 3–4 nằm trên đường găng và không nơi nào còn công suất.","Sai: tuần 5 chỉ còn trống 160 − 140 = 20 giờ, trong khi cần chuyển 40 + 50 = 90 giờ. Dồn vào tuần 5 sẽ làm tuần 5 quá tải.","Đúng: quá tải tuần 3 là 200 − 160 = 40 giờ và tuần 4 là 210 − 160 = 50 giờ, tổng 90 giờ. Các tuần 6–8 còn trống 70 + 60 + 80 = 210 giờ, và việc không găng có 4 tuần float, nên resource smoothing (dời trong float) giữ nguyên đường găng và ngày kết thúc."],exp:"Task R4 (quản lý nguồn lực — resources): resource smoothing điều chỉnh hoạt động trong float để san phẳng đỉnh mà không đổi ngày kết thúc; resource levelling chấp nhận đổi ngày để tuân theo giới hạn nguồn lực. Quy tắc nhớ: ngày cố định và còn float thì smoothing; nguồn lực cứng và ngày linh hoạt thì levelling. Bẫy: dồn việc vào tuần kế tiếp mà không kiểm tra công suất còn lại."},{id:"o526",n:526,t:0,origin:"original",eco:"B5",domain:"business",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","emv","contingency"],type:"mc",exhibit:{title:"Risk register extract: threats",kind:"table",unit:"$ thousand",columns:["Risk","Probability (%)","Impact ($ thousand)","EMV ($ thousand)"],rows:[["Supplier delivers late",40,50,20],["Soil contamination found",10,300,30],["Permit approval delayed",60,20,12],["Key welder leaves",25,40,10],["Steel price rises",30,90,27]],note:"EMV = probability × impact."},q:"A project manager for a bridge-approach road project is preparing the risk section of the baseline for the sponsor. The sponsor's policy is that the contingency reserve equals the total expected monetary value of all threats in the register, and that the threat with the highest expected loss gets a named response owner first. What should the project manager recommend?",opts:["Hold a contingency reserve of $300,000, which covers the largest single impact in the register, and name an owner for the soil contamination risk","Hold a contingency reserve of $99,000, the total EMV of the five threats, and name an owner for the soil contamination risk first","Hold a contingency reserve of $99,000, the total EMV of the five threats, and name an owner for the permit delay, the most likely threat","Hold a contingency reserve of $69,000 for the four threats above 10 percent probability, and name an owner for the steel price risk"],ans:[1],why:["Sai: $300.000 là tác động lớn nhất của một rủi ro đơn lẻ, nhưng xác suất chỉ 10 % (EMV $30.000). Chính sách của sponsor đặt dự phòng bằng tổng EMV, nên giữ 300.000 là quá mức dù chọn đúng chủ sở hữu.","Đúng: EMV = xác suất × tác động, tổng 20 + 30 + 12 + 10 + 27 = $99.000. Rủi ro đất ô nhiễm có EMV cao nhất ($30.000 = 10 % × $300.000) nên được gán chủ sở hữu phản ứng đầu tiên.","Sai: số tiền $99.000 đúng, nhưng permit delay chỉ có EMV $12.000 (60 % × $20.000). Khả năng xảy ra cao nhất không bằng tổn thất kỳ vọng cao nhất, và chính sách yêu cầu chọn theo tổn thất kỳ vọng.","Sai: $69.000 chỉ là EMV của bốn rủi ro còn lại (20 + 12 + 10 + 27), bỏ rủi ro đất ô nhiễm vì xác suất thấp. Chính sách tính mọi threat trong register, và người sở hữu đầu tiên phải ứng với EMV cao nhất chứ không phải cao thứ hai."],exp:'Task B5 "Plan and manage risk": EMV = xác suất × tác động, và tổng EMV của các threat là một cách định cỡ contingency phổ biến; ưu tiên phản ứng theo EMV (hoặc điểm rủi ro) chứ không theo riêng xác suất hay riêng tác động. Bẫy: nhầm "khả năng xảy ra cao nhất" hoặc "tác động lớn nhất" với "tổn thất kỳ vọng cao nhất".'},{id:"o527",n:527,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["agile","eco-2026","format-2026","graphic","value-delivery","backlog-priority"],type:"mc",exhibit:{title:"Value added by each release compared with its cost",kind:"line",unit:"$ thousand",columns:["Release","First-year benefit added","Cost of release"],rows:[["R1",150,60],["R2",120,60],["R3",80,60],["R4",50,60],["R5",30,60],["R6",20,60]],note:"The cost of a release is constant. The roadmap approved last year plans ten releases."},q:"An agile team delivers a customer self-service portal in monthly releases. After release 6, the product owner proposes to continue with releases 7 to 10 exactly as the roadmap was written a year ago, and asks the project manager for a view on the plan. The chart shows the benefit each release has added and what it cost. What should the project manager recommend?",opts:["Show the product owner that releases 4 to 6 each cost more than the benefit they added, and recommend re-ranking the backlog before anyone funds release 7","Continue with releases 7 to 10 as planned, because the steering committee approved the roadmap and later features often add less value than early ones","Cut the cost of each release below the $20,000 benefit of release 6 by dropping regression testing, so that the cost line falls under the benefit line","Ask the team to raise its velocity so that each release carries more features, which will lift the benefit line back above the cost line"],ans:[0],why:["Đúng: benefit của R4, R5, R6 là 50, 30, 20, đều thấp hơn chi phí 60 của mỗi release. Đây là dữ liệu để product owner xếp lại backlog theo giá trị trước khi chi tiền cho release 7, thay vì chạy tiếp roadmap viết từ năm trước.","Sai: roadmap được duyệt từ năm ngoái, trước khi có dữ liệu thực. Giá trị giảm dần là bình thường, nhưng ba release gần nhất tốn 60 mà chỉ thêm 50, 30, 20, nên bám kế hoạch cũ là bỏ qua bằng chứng.","Sai: bỏ regression testing để hạ chi phí đánh đổi chất lượng và tăng rủi ro lỗi cho khách hàng, trong khi vấn đề thật là giá trị mỗi release giảm. Sẽ đúng nếu có lãng phí thật được chỉ ra trong quy trình release.","Sai: tăng velocity là tăng lượng việc làm ra, không phải giá trị. Các tính năng còn lại trong roadmap có giá trị thấp nên làm nhiều hơn vẫn không kéo đường benefit lên."],exp:"Task R3 (phạm vi và giá trị — value-based delivery): trong agile, quyết định tiếp tục hay dừng dựa trên giá trị thu được so với chi phí, và product owner là người xếp lại backlog. Quy tắc nhớ: đường benefit rơi xuống dưới đường chi phí là tín hiệu xem lại ưu tiên, không phải tín hiệu tăng tốc. Bẫy: bám roadmap cũ hoặc cắt chất lượng để giữ nhịp release."},{id:"o528",n:528,t:0,origin:"original",eco:"P6",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","graphic","customer-satisfaction","expectations"],type:"mc",exhibit:{title:"Customer satisfaction by user group",kind:"bar",unit:"% satisfied",columns:["User group","March survey","June survey"],rows:[["Nurses",82,85],["Doctors",78,80],["Admin staff",80,82],["Pharmacy",84,55],["Finance",74,78]],note:"Agreed target: every user group at or above 70 percent satisfied."},q:"A hybrid project is rolling out a new patient-records system in phases. The June satisfaction survey results are shown. The sponsor's dashboard shows an average of 76 percent satisfied across the five groups, and the project manager is deciding how to respond before the next phase starts. What is the best action?",opts:["Send a second survey to all five user groups to confirm that the pharmacy drop is real before the project manager changes any plan for the next phase","Ask the product owner to place every pharmacy request received so far at the top of the backlog for the next phase, ahead of all other items","Meet the pharmacy leads to learn which expectations changed since March, then agree with the product owner how the next phase responds","Report the 76 percent average to the sponsor as meeting the target and continue the rollout plan for the next phase unchanged"],ans:[2],why:["Sai: khảo sát lần hai trên cả năm nhóm làm chậm phản ứng, trong khi dữ liệu tháng 6 đã chỉ rõ nhóm Pharmacy giảm từ 84 xuống 55. Sẽ đúng nếu kết quả mâu thuẫn nhau hoặc cỡ mẫu quá nhỏ để tin.","Sai: đưa mọi yêu cầu của Pharmacy lên đầu backlog là phản ứng khi chưa hiểu nguyên nhân và vượt quyền ưu tiên của product owner. Kỳ vọng có thể đã đổi; cần hiểu trước khi ưu tiên.","Đúng: Pharmacy tụt 29 điểm và nằm dưới ngưỡng 70 % đã thỏa thuận. PM gặp trực tiếp nhóm này để biết kỳ vọng nào đã thay đổi từ tháng 3, rồi cùng product owner quyết định giai đoạn tới đáp ứng ra sao.",'Sai: trung bình 76 % che mất việc Pharmacy ở mức 55 %. Mục tiêu thỏa thuận áp cho từng nhóm chứ không phải trung bình, nên báo "đạt" là sai. Sẽ đúng nếu mục tiêu chỉ tính trên trung bình chung.'],exp:'Task P6, enabler "monitor customer satisfaction/expectations and respond as needed": nhìn dữ liệu theo nhóm, không chỉ trung bình, vì kỳ vọng của một nhóm có thể lệch trong khi tổng thể vẫn xanh. Quy tắc nhớ: phát hiện lệch, trò chuyện trực tiếp để hiểu kỳ vọng mới, rồi cùng product owner điều chỉnh. Bẫy: tin con số trung bình hoặc phản ứng bằng cách nhận mọi yêu cầu.'},{id:"o529",n:529,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","vendor-selection","weighted-scoring"],type:"mc",exhibit:{title:"Weighted vendor scorecard",kind:"table",columns:["Criterion","Weight (%)","Vendor X","Vendor Y","Vendor Z"],rows:[["Technical solution",40,8,7,9],["Price",25,6,9,5],["Delivery plan",20,7,8,6],["Support",15,9,6,7]],note:"Scores run from 1 to 10, higher is better. The criteria and weights were published in the request for proposal and cannot change."},q:"A project manager is leading the selection of a vendor for a warehouse management system under a predictive plan. The evaluation panel scored three vendors as shown, and the contract will go to the vendor with the best result on the published criteria. Which vendor should the project manager recommend?",opts:["Vendor Z, because it scored highest on the technical solution, which carries the largest weight of the four criteria","Vendor X, because its technical and support scores together are the highest of the three vendors at 17 points","Vendor X or Vendor Y, because both have an unweighted average of 7.5, so the panel should settle the tie on price","Vendor Y, because its weighted total of 7.55 is the highest of the three vendors on the published criteria"],ans:[3],why:["Sai: Vendor Z đứng đầu về kỹ thuật (9) nhưng điểm có trọng số chỉ 7,10 (3,60 + 1,25 + 1,20 + 1,05) vì giá chỉ 5 và giao hàng 6. Tiêu chí có trọng số lớn nhất không có nghĩa là chỉ cần nhìn tiêu chí đó.","Sai: cộng điểm kỹ thuật và hỗ trợ (8 + 9 = 17) bỏ qua trọng số đã công bố (40 % và 15 %) và hai tiêu chí còn lại. Điểm có trọng số của X là 7,45, thấp hơn Y.","Sai: điểm trung bình không trọng số của X và Y đều là 7,5, nhưng RFP đã công bố trọng số nên không được coi là hòa. Dùng trọng số thì Y (7,55) hơn X (7,45).","Đúng: Y = 7×0,40 + 9×0,25 + 8×0,20 + 6×0,15 = 2,80 + 2,25 + 1,60 + 0,90 = 7,55; X = 7,45; Z = 7,10. Tiêu chí và trọng số đã công bố trong RFP, nên chọn nhà thầu có điểm có trọng số cao nhất."],exp:"Task R5 (mua sắm — procurement): chọn nhà thầu theo tiêu chí và trọng số đã công bố, tính điểm có trọng số bằng điểm nhân trọng số rồi cộng. Quy tắc nhớ: không đổi tiêu chí hay trọng số sau khi nhận đề xuất, vì mất tính công bằng. Bẫy: chọn theo tiêu chí lớn nhất, theo điểm trung bình không trọng số hoặc theo cảm nhận."},{id:"o530",n:530,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","control-chart","rule-of-seven"],type:"mc",exhibit:{title:"Control chart: fill weight of sample packs",kind:"line",unit:"grams",columns:["Sample","Measured weight","UCL","LCL"],rows:[["1",497,512,488],["2",502,512,488],["3",503,512,488],["4",501,512,488],["5",505,512,488],["6",504,512,488],["7",506,512,488],["8",505,512,488]],note:"Centre line (mean): 500 g. Customer specification: 480 g to 520 g. One sample pack is weighed per hour."},q:"A packaging line follows a predictive quality plan, and the fill weight of one sample pack per hour is plotted on the control chart shown. The operator reports that no point has crossed a control limit and suggests simply carrying on to the end of the shift. What should the project manager conclude and do?",opts:["The process is in control because every point lies inside the control limits, so production continues and sampling stays as planned","The latest seven points all sit above the mean, a non-random pattern, so the team looks for an assignable cause before more output is produced","The process is out of specification because the later samples are heavier than the mean, so the batch is rejected and the packs are refilled","The control limits are wrong because the points no longer centre on 500 g, so the limits are recalculated from the latest seven samples"],ans:[1],why:["Sai: mọi điểm nằm trong UCL và LCL, nhưng bảy điểm liên tiếp (mẫu 2–8) cùng nằm trên đường trung bình 500 g là tín hiệu quy tắc bảy: quá trình có nguyên nhân bất thường dù chưa vượt giới hạn.","Đúng: mẫu 2 đến mẫu 8 đều trên 500 g (502, 503, 501, 505, 504, 506, 505), bảy điểm liên tiếp cùng một phía. Đây là mẫu không ngẫu nhiên, nên cần tìm assignable cause (ví dụ máy, nguyên liệu) trước khi sản xuất thêm.","Sai: giới hạn đặc tả của khách là 480–520 g và mọi mẫu đều nằm trong đó, nên chưa có sản phẩm ngoài đặc tả để loại bỏ. Control limits và specification limits là hai khái niệm khác nhau.","Sai: tính lại giới hạn từ bảy mẫu gần nhất làm tín hiệu biến mất thay vì tìm nguyên nhân. Chỉ nên tính lại giới hạn sau khi nguyên nhân đã được xác định và quá trình đã được sửa."],exp:"Task R7 (chất lượng — quality): control chart có hai loại tín hiệu, điểm vượt giới hạn và mẫu không ngẫu nhiên, trong đó quy tắc bảy là bảy điểm liên tiếp cùng một phía đường trung bình. Quy tắc nhớ: trong giới hạn kiểm soát chưa chắc là trong kiểm soát; thấy tín hiệu thì điều tra nguyên nhân gốc trước khi chỉnh. Bẫy: nhầm control limits với specification limits."},{id:"o531",n:531,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["agile","eco-2026","format-2026","graphic","team-health","servant-leadership"],type:"mc",exhibit:{title:"Team health check, average score",kind:"bar",unit:"score (1 = poor, 5 = excellent)",columns:["Dimension","Last quarter","This quarter"],rows:[["Clear goals",4.2,4.3],["Collaboration",4,4.1],["Technical quality",3.9,3.9],["Learning",3.7,3.8],["Sustainable pace",3.6,2.2],["Trust",4.1,4]],note:"Anonymous survey of the nine team members."},q:"A self-organising agile team of nine ran its quarterly health check, and the results are shown. In the retrospective notes the team says that urgent requests from the customer-support department now arrive in the middle of nearly every sprint. The project manager serves the team as a servant leader. What is the best next step?",opts:["Present the results to the department head and request overtime pay so that the team can absorb the mid-sprint requests from support","Extend the sprint from two weeks to three so that the urgent requests from the support department can be fitted into each sprint","Take the pace score to the retrospective so the team chooses its own changes, and work with support to end mid-sprint requests","Interview each team member privately and then set new working-hours rules for the whole team to follow from the next sprint onward"],ans:[2],why:["Sai: xin tiền làm thêm giờ là bù đắp triệu chứng và đưa vấn đề lên người ngoài đội trước khi đội thảo luận. Nguyên nhân là yêu cầu khẩn cấp giữa sprint, nên cần giảm nó chứ không phải trả tiền để chịu nó.","Sai: kéo sprint từ hai lên ba tuần đổi nhịp của cả đội mà không do đội quyết định, và yêu cầu khẩn cấp vẫn chen vào giữa sprint. Sẽ đúng nếu chính đội đề xuất đổi độ dài sprint trong retrospective.","Đúng: điểm sustainable pace tụt từ 3,6 xuống 2,2 trong khi các mục khác gần như ổn. Đội tự tổ chức nên PM đưa kết quả vào retrospective để đội tự chọn thay đổi, rồi đóng vai servant leader gỡ nguyên nhân bên ngoài (yêu cầu của bộ phận support).","Sai: phỏng vấn riêng rồi tự đặt quy định giờ làm là kiểu chỉ huy, làm giảm quyền tự chủ của đội tự tổ chức. Sẽ đúng nếu đội yêu cầu PM đặt quy định thay cho họ."],exp:"Task P3 (lãnh đạo đội — lead the project team): với đội agile tự tổ chức, PM là servant leader: đưa dữ liệu cho đội, để đội tự quyết cách cải thiện và gỡ trở ngại bên ngoài. Quy tắc nhớ: đội sở hữu cách làm, PM sở hữu việc gỡ trở ngại. Bẫy: giải pháp chỉ huy từ trên xuống hoặc đổi nhịp làm việc thay cho đội."},{id:"o532",n:532,t:0,origin:"original",eco:"B8",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","graphic","external-change","business-case"],type:"mr",exhibit:{title:"Quarterly market demand forecast compared with the business case",kind:"line",unit:"thousand units",columns:["Quarter","Updated demand forecast","Business case assumption"],rows:[["Q1",30,30],["Q2",31,30],["Q3",28,30],["Q4",24,30],["Q5",20,30],["Q6",17,30]],note:"Break-even demand in the business case: 22 thousand units per quarter. The project is about 60 percent complete."},q:"A hybrid project is building a new line of smart thermostats. Mid-project, a competitor's launch and a change in import prices have pushed market demand down, as the updated forecast shows. The sponsor has not yet commented, and the project manager must respond to this external change. Which two actions should the project manager take? (Choose two.)",opts:["Update the benefits forecast with the new demand and take the revised business case to the sponsor for a continue, change or stop decision","Work with the product owner to re-rank the remaining backlog and defer features that rely on the sales volumes in the original business case","Continue the plan unchanged, because market demand is outside the control of the project and the approved business case still stands as the baseline for benefits","Pay for extra marketing from the contingency reserve to push demand back up to the 30 thousand units assumed in the business case","Pause all spending until the demand forecast has stayed above the break-even level of 22 thousand units for two quarters in a row"],ans:[0,1],why:["Đúng: demand rơi từ 30 xuống 17 và đã dưới điểm hòa vốn 22 từ quý 5, nên lợi ích của business case thay đổi. Cập nhật dự báo lợi ích và đưa business case mới cho sponsor để quyết định tiếp tục, đổi hướng hay dừng.","Đúng: dự án còn khoảng 40 % công việc. Ưu tiên lại backlog cùng product owner và hoãn các tính năng phụ thuộc vào sản lượng ban đầu giúp chi tiêu cho phần còn lại khớp với nhu cầu thấp hơn.",'Sai: nhu cầu nằm ngoài tầm kiểm soát của dự án, nhưng ảnh hưởng của nó lên business case thì PM phải theo dõi và báo. Giữ nguyên kế hoạch vì "business case đã duyệt" là bỏ qua thay đổi bên ngoài.',"Sai: contingency là dự phòng cho rủi ro của dự án, dùng nó để mua marketing nằm ngoài mục đích của quỹ này. Kéo nhu cầu thị trường lên là việc của bộ phận kinh doanh, không phải của dự án.","Sai: dừng toàn bộ chi tiêu cho tới khi nhu cầu trên 22 nghìn trong hai quý liên tiếp là phản ứng cực đoan và có thể kéo dài vô hạn. Quyết định dừng hay tiếp tục thuộc sponsor sau khi có business case cập nhật."],exp:'Task B8 (môi trường bên ngoài — external business environment): khi thay đổi bên ngoài làm lệch business case, PM đánh giá ảnh hưởng, cập nhật dự báo lợi ích và để sponsor quyết định hướng đi; cùng lúc PM điều chỉnh phạm vi còn lại với product owner. Quy tắc nhớ: đo tác động trước, đề xuất phương án sau, quyết định của dự án thuộc sponsor. Bẫy: làm ngơ vì "ngoài tầm kiểm soát", hoặc dừng toàn bộ.'},{id:"o533",n:533,t:0,origin:"original",eco:"P4",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","graphic","stakeholder-analysis","power-interest"],type:"mr",exhibit:{title:"Stakeholder register extract",kind:"table",columns:["Stakeholder","Power","Interest","Attitude to go-live"],rows:[["Regional director","High","High","Resistant"],["Finance controller","High","Low","Neutral"],["Customer council","High","High","Supportive"],["Floor supervisors","Low","High","Supportive"],["Facilities contractor","Low","Low","Neutral"]],note:"Only the stakeholders with high power vote at the steering committee."},q:"A hybrid project to change the ordering process in a retail chain goes to a steering committee vote on go-live in two weeks. The project manager has time for only two engagement actions before then and uses the stakeholder register extract shown. Which two actions will best improve the chance of a positive vote? (Choose two.)",opts:["Meet the regional director one to one to understand the concerns behind the resistance and agree what would address them","Ask the customer council to present its evidence of benefit to the steering committee as a supportive voice ahead of the vote","Hold weekly workshops with the floor supervisors, since they have the highest interest in the new ordering process and will use it daily","Keep the regional director informed through the monthly report only, so that the resistance is not given more attention","Invite the facilities contractor to present the installation plan to the steering committee as a neutral party before the vote on go-live"],ans:[0,1],why:["Đúng: giám đốc vùng có quyền lực cao, quan tâm cao nhưng đang phản đối, và có phiếu bầu. Gặp riêng để hiểu mối lo và thống nhất điều gì giải quyết được nó là ưu tiên số một trong hai tuần.","Đúng: customer council quyền lực cao, quan tâm cao và ủng hộ. Mời họ trình bày bằng chứng lợi ích trước steering committee là tận dụng người ủng hộ có trọng lượng ngay trước cuộc bỏ phiếu.","Sai: floor supervisors quan tâm cao nhưng quyền lực thấp và không có phiếu. Họp hằng tuần với họ là hợp lý về lâu dài (keep informed) nhưng không nằm trong hai việc quyết định kết quả phiếu trong hai tuần.","Sai: chỉ gửi báo cáo tháng cho người đang phản đối và có phiếu là né mối lo của họ, rủi ro nhất cho kết quả bỏ phiếu. Sẽ đúng nếu người đó có quyền lực thấp hoặc đã ủng hộ.","Sai: facilities contractor quyền lực thấp, quan tâm thấp và trung lập; trình bày trước steering committee không thay đổi lá phiếu nào. Với nhóm này chỉ cần theo dõi (monitor)."],exp:'Task P4 (engage stakeholders): dùng lưới quyền lực và quan tâm để chọn người ưu tiên; nhóm quyền lực cao và quan tâm cao (manage closely) cần thời gian trực tiếp nhất, cả người phản đối lẫn người ủng hộ. Quy tắc nhớ: khi thời gian hạn chế, đầu tư vào người tác động tới quyết định. Bẫy: chọn nhóm "quan tâm nhất" thay vì "ảnh hưởng nhất", hoặc né người phản đối.'},{id:"o534",n:534,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["predictive","eco-2026","format-2026","graphic","governance","change-approval"],type:"mc",exhibit:{title:"Governance thresholds for approving a change",kind:"table",columns:["Level","Cost impact","Schedule impact","Approver"],rows:[["1","up to $10,000","up to 3 days","Project manager"],["2","up to $50,000","up to 2 weeks","Change control board"],["3","up to $200,000","up to 6 weeks","Steering committee"],["4","above $200,000","above 6 weeks","Sponsor and executive board"]],note:"A change is approved at the highest level reached by either its cost impact or its schedule impact."},q:"A predictive construction project follows the governance rules shown for approving changes. The client asks for a different floor finish that would cost $35,000 and delay handover by three weeks. The project manager is preparing the change request for submission. Who must approve this change?",opts:["The steering committee, because the three-week delay puts the change at level 3 although its $35,000 cost alone sits in level 2","The change control board, because the $35,000 cost sits in level 2 and the cost is usually the main measure of the size of a change","The project manager, because the finish is a client request and the delay can be recovered later by compressing the schedule","The sponsor and executive board, because any change that delays handover to the client has to be escalated to the very top level of approval"],ans:[0],why:["Đúng: chi phí $35.000 thuộc cấp 2 nhưng trễ ba tuần vượt giới hạn hai tuần của cấp 2, rơi vào cấp 3. Quy tắc trong bảng là phê duyệt theo cấp cao nhất mà chi phí hoặc tiến độ chạm tới, nên steering committee duyệt.","Sai: change control board chỉ duyệt thay đổi tới $50.000 và tới hai tuần. Nếu chỉ nhìn chi phí thì đúng, nhưng bảng nói tiêu chí nào chạm cấp cao hơn sẽ quyết định cấp.","Sai: PM chỉ tự duyệt thay đổi tới $10.000 và 3 ngày. Khả năng bù trễ bằng nén tiến độ về sau không phải căn cứ để hạ cấp phê duyệt.",'Sai: cấp 4 chỉ dành cho thay đổi trên $200.000 hoặc trễ trên sáu tuần. Trễ ba tuần chưa tới ngưỡng này, và "ảnh hưởng bàn giao" không được ghi là điều kiện leo lên cấp cao nhất.'],exp:"Task B1 (governance): thẩm quyền duyệt thay đổi nằm ở bảng ngưỡng do tổ chức đặt; PM áp đúng bảng, không đoán và không tự nâng hay hạ cấp. Quy tắc nhớ: khi chi phí và tiến độ cho hai cấp khác nhau, cấp cao hơn quyết định (nếu bảng ghi như vậy). Bẫy: chỉ nhìn tiền mà quên tiến độ."},{id:"o535",n:535,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["agile","eco-2026","format-2026","graphic","compliance","security-gate"],type:"mr",exhibit:{title:"Open security scan findings at the end of each sprint",kind:"bar",unit:"findings",columns:["Sprint","Critical","High","Medium"],rows:[["S1",2,5,9],["S2",1,6,10],["S3",1,4,8],["S4",0,5,9],["S5",1,3,7],["S6",1,4,6]],note:"Release policy: no open critical finding and no more than three open high findings. Release candidate: end of sprint 6."},q:"An agile team is preparing the first public release of a payments feature at the end of sprint 6. The compliance gate in the release policy requires a clean security scan before go-live, and the results at the end of each sprint are shown. The product owner wants to keep the release date because of a marketing event. Which two actions should the project manager take? (Choose two.)",opts:["Hold the release candidate until a rescan shows no open critical finding and no more than three open high findings","Agree a fix-and-rescan plan with the security lead and the product owner, with the open critical and high findings first in the backlog","Release on the planned date for the marketing event, and schedule the fixes for the critical finding in the first sprint after the go-live","Raise the high-finding limit in the release policy from three to five so that the sprint 6 build passes the compliance gate on time","Limit future scans to the modules changed in each sprint so that the scan finishes before each release candidate is built"],ans:[0,1],why:["Đúng: sprint 6 còn 1 lỗi critical và 4 lỗi high, vượt chính sách (không critical, tối đa 3 high). Compliance gate phải đạt trước khi phát hành, nên giữ release candidate cho tới khi quét lại đạt.","Đúng: kế hoạch sửa và quét lại thống nhất với security lead và product owner, đưa lỗi critical và high lên đầu backlog, vừa tôn trọng quyền ưu tiên của product owner vừa đưa bản phát hành về mức đạt.","Sai: phát hành khi còn lỗi critical mở là vi phạm cổng tuân thủ, và lỗi trên tính năng thanh toán có thể gây hậu quả pháp lý. Sự kiện marketing không phải căn cứ để bỏ qua chính sách.","Sai: nâng ngưỡng high lên năm chỉ để bản sprint 6 qua cổng là sửa luật theo kết quả, và lỗi critical mở vẫn khiến bản build không đạt. Chính sách chỉ đổi qua quy trình quản trị, không đổi để hợp thức hóa một bản build.","Sai: chỉ quét module đã thay đổi làm giảm độ phủ của compliance gate; lỗi có thể nằm ở phần tương tác với module khác. Mục tiêu là giảm thời gian quét bằng tự động hóa, không phải thu hẹp phạm vi kiểm tra."],exp:"Task B2 (tuân thủ — compliance): cổng tuân thủ là tiêu chí phát hành do chính sách đặt ra, không phải khuyến nghị. Trong agile, kết quả quét bảo mật là một phần của definition of done và việc sửa lỗi vào backlog theo ưu tiên của product owner. Quy tắc nhớ: không hạ chuẩn hay bỏ cổng để giữ ngày. Bẫy: coi lịch marketing quan trọng hơn chính sách."},{id:"o536",n:536,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","multiple-response","common-vision","alignment"],type:"mr",q:"A hybrid project will merge the order-handling processes of the Sales and Operations departments. Sales describes the goal as faster quotes for customers, while Operations describes it as fewer shipping errors, and each department expects the new process to follow its own description. The project manager must develop a common vision. Which two actions should the project manager take? (Choose two.)",opts:["Run a joint workshop with leaders from both departments to describe the outcome each expects and draft one vision statement","Review the draft vision with the sponsor and both department heads, then publish it and refer to it in planning and status meetings","Adopt the Sales description as the project vision, since Sales funds most of the work, and brief the Operations department on it afterwards","Wait for the detailed requirements phase to finish, because a vision is written from the requirements once all of them are known","Send the project charter to both departments and treat silence over the following week as agreement with the vision"],ans:[0,1],why:["Đúng: hai phòng mô tả mục tiêu khác nhau, nên PM tổ chức workshop chung để mỗi bên nói kết quả mình mong và cùng soạn một câu vision. Tầm nhìn chung được xây cùng nhau, không áp từ một phía.","Đúng: sau khi có bản nháp, PM rà soát với sponsor và hai trưởng phòng rồi công bố, và dùng lại trong họp kế hoạch và báo cáo để mọi người nhớ cùng một đích. Như vậy tầm nhìn có cam kết của cả hai phía.","Sai: chọn mô tả của Sales vì Sales chi nhiều tiền làm Operations bị gạt ra và không còn thấy mình trong dự án. Sẽ đúng nếu chính Operations nói họ đồng ý với mô tả của Sales.","Sai: vision là điểm xuất phát để thu thập yêu cầu, không phải sản phẩm của giai đoạn yêu cầu. Chờ yêu cầu xong mới viết vision khiến hai phòng tiếp tục kéo yêu cầu về hai hướng khác nhau.","Sai: coi im lặng một tuần là đồng ý là giả định không có bằng chứng. Hai phòng đang bất đồng, nên cần đối thoại trực tiếp để xác nhận cùng hiểu một mục tiêu."],exp:"Task P1 (Develop a common vision): tầm nhìn chung không do một phía viết rồi gửi đi mà hình thành qua đối thoại với các bên có kỳ vọng khác nhau, sau đó được sponsor và các bên xác nhận và lặp lại thường xuyên. Quy tắc nhớ: cùng tạo, cùng xác nhận, cùng nhắc lại. Bẫy: chọn phía mạnh hơn, hoặc coi im lặng là đồng ý."},{id:"o537",n:537,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["agile","eco-2026","format-2026","multiple-response","conflict","product-owner"],type:"mr",q:"In an agile project to rebuild a billing portal, the head of the collections department asks the project manager to overrule the product owner, who moved the head's requested report to the end of the backlog. The head says the product owner ignores collections, while the product owner says the report adds little value now. Which two actions should the project manager take first? (Choose two.)",opts:["Speak with the product owner and the head of collections separately about the interests and facts behind each position","Bring both together to agree the value criteria used to order the backlog, then apply them to the requested report","Instruct the product owner to move the report into the current sprint so that the head of collections is satisfied with the outcome","Ask the sponsor to decide between the two and announce the ruling to the whole team at the next sprint review","Record the disagreement in the issue log and review it at the next retrospective with the whole team present"],ans:[0,1],why:["Đúng: gặp riêng từng người giúp PM nghe lợi ích và dữ kiện đằng sau lập trường trước khi hai bên đối đầu. Bước này tìm nguyên nhân gốc của xung đột.","Đúng: sau khi hiểu cả hai phía, PM tạo điều kiện để họ thống nhất tiêu chí giá trị dùng sắp xếp backlog, rồi áp dụng cho báo cáo này. Product owner vẫn giữ quyền ưu tiên, còn trưởng phòng thấy lý do rõ ràng.","Sai: ra lệnh cho product owner đưa báo cáo vào sprint hiện tại phá quyền ưu tiên backlog và chuyển xung đột vào giữa đội. Sẽ đúng nếu product owner tự đồng ý sau khi thấy dữ liệu giá trị.","Sai: nhờ sponsor phán quyết khi hai bên chưa nói chuyện với nhau là leo thang quá sớm. Chỉ nhờ sponsor khi PM đã tạo điều kiện hợp tác mà vẫn không giải quyết được.","Sai: ghi vào issue log rồi để cho retrospective xử lý để mặc xung đột kéo dài, trong khi một bên là người ngoài đội và retrospective không phải nơi dành cho việc này. Xung đột cần được giải quyết trực tiếp ngay giữa các bên."],exp:"Task P2 (Manage conflicts): giải quyết xung đột bắt đầu bằng việc hiểu nguồn gốc (lợi ích, dữ kiện) rồi tạo điều kiện cho các bên cùng tìm giải pháp; PM không phán quyết thay và không phá quyền của product owner. Quy tắc nhớ: hiểu trước, hợp tác sau, leo thang cuối cùng. Bẫy: ra lệnh làm hài lòng người than phiền, hoặc đẩy lên sponsor ngay."},{id:"o538",n:538,t:0,origin:"original",eco:"B7",domain:"business",approach:"predictive",tags:["predictive","eco-2026","format-2026","multiple-response","change-management","resistance"],type:"mr",q:"A predictive project will move the accounts payable team of 25 people to a new invoice-approval system in three weeks. In recent briefings many of them said that the new process adds steps and that the old one works well. The sponsor wants a smooth go-live on the planned date. Which three actions should the project manager take? (Choose three.)",opts:["Talk with affected staff and their supervisors to find the specific concerns behind the resistance and what changes for each role","Recruit respected team members as change champions who try the system first, show it to colleagues and report problems early","Schedule hands-on training and a support desk for the first weeks after go-live, and share the plan with staff in advance","Have the sponsor announce that the old process will be withdrawn on the go-live date and that its use afterwards is not allowed for any team","Remove the approval steps that staff dislike directly in the system, then inform the change control board afterwards"],ans:[0,1,2],why:["Đúng: nói chuyện với nhân viên và giám sát để biết mối lo cụ thể (thêm bước, mất thói quen) cho phép điều chỉnh đào tạo và hỗ trợ. Hiểu nguyên nhân kháng cự là bước đầu của quản lý thay đổi.","Đúng: change champion là người được đồng nghiệp tôn trọng, dùng thử hệ thống sớm và nói với đồng nghiệp bằng ngôn ngữ của nghề, giúp giảm kháng cự hiệu quả hơn lời của PM.","Đúng: đào tạo thực hành và bàn hỗ trợ trong những tuần đầu đưa thay đổi từ thông báo thành năng lực thực tế. Chia sẻ kế hoạch từ trước cho nhân viên thấy họ không bị bỏ rơi.","Sai: thông báo rút quy trình cũ khi chưa nghe mối lo là ép buộc, thường tăng kháng cự và bị lách ngầm. Sẽ đúng như bước cuối sau khi đã đào tạo và hỗ trợ.","Sai: sửa các bước duyệt trực tiếp trong hệ thống rồi báo change control board sau là qua mặt kiểm soát thay đổi, có thể phá yêu cầu kiểm soát nội bộ. Mọi sửa đổi phải đi qua quy trình change request."],exp:"Task B7 (thay đổi tổ chức — organisational change): kháng cự là dữ liệu. Ba việc đi cùng nhau: hiểu mối lo, dùng người có ảnh hưởng nội bộ (champion) và cho đào tạo cùng hỗ trợ. Quy tắc nhớ: change management là làm cùng người dùng, không làm thay hay ép họ. Bẫy: ép bằng mệnh lệnh hoặc sửa hệ thống để lấy lòng người dùng mà bỏ qua kiểm soát thay đổi."},{id:"o539",n:539,t:0,origin:"original",eco:"P8",domain:"people",approach:"agile",tags:["agile","eco-2026","format-2026","multiple-response","distributed-team","async-communication"],type:"mr",q:"An agile team of eleven develops a mobile app with members in Manila, Berlin and São Paulo, and the three locations share very few working hours. Decisions are being delayed because people wait for the daily stand-up, and the Manila members say that every live meeting falls at the end of their evening. Which two actions should the project manager take? (Choose two.)",opts:["Agree in a team working agreement which decisions are made in writing on the shared board and which need a live talk","Rotate the time of the live ceremonies so that no single location always meets at the end of its working day","Move the daily stand-up to the one slot that suits Berlin and make attendance compulsory for all eleven members of the team","Ask each team lead to relay decisions to their own location by email so that the team does not need shared meetings at all","Replace the daily stand-up with a weekly status report that the project manager compiles and sends to all members"],ans:[0,1],why:["Đúng: working agreement ghi rõ quyết định nào làm bằng văn bản trên bảng chung và quyết định nào cần nói chuyện trực tiếp, nên không ai phải chờ cuộc họp hằng ngày để đi tiếp.","Đúng: luân phiên giờ họp chia đều gánh nặng múi giờ, tránh để nhóm Manila luôn họp vào cuối buổi tối. Đây là cách giữ sự công bằng và sức khỏe của đội phân tán.","Sai: ép mọi người dự một khung giờ hợp với Berlin biến gánh nặng múi giờ thành bất công kéo dài cho hai nơi còn lại. Sẽ đúng nếu cả ba nơi cùng đồng ý khung giờ đó.","Sai: truyền quyết định qua email của các team lead biến lead thành trạm trung chuyển, thêm độ trễ và dễ sai lệch. Đội phân tán cần thông tin minh bạch trên công cụ chung.","Sai: thay stand-up hằng ngày bằng báo cáo tuần do PM tổng hợp làm mất nhịp đồng bộ của đội agile và dồn việc cho một người. Có thể bổ sung cập nhật bất đồng bộ nhưng không bỏ hẳn nhịp hằng ngày."],exp:"Task P8 (giao tiếp và báo cáo — communication): đội phân tán nhiều múi giờ cần thỏa thuận làm việc rõ ràng, kênh bất đồng bộ cho quyết định thường ngày, và chia đều gánh nặng giờ họp. Quy tắc nhớ: minh bạch trên công cụ chung, công bằng về múi giờ. Bẫy: bắt cả đội theo giờ của một nơi hoặc thay giao tiếp của đội bằng báo cáo do PM tổng hợp."},{id:"o540",n:540,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","multiple-response","scope-creep","traceability"],type:"mr",q:"On a predictive software project with an approved scope baseline, the client's staff have begun asking developers directly for small extras, and the developers have built several of them. The requirements traceability matrix lists 14 requirements, and the current build contains features that link to none of them. Which two actions should the project manager take? (Choose two.)",opts:["Route every request through change control, comparing it with the scope baseline and the traceability matrix before any work starts","Agree that requests are logged and sent to the business analyst, who links each approved one to a requirement","Let developers build any request that takes under four hours without analysis, because small extras do not affect cost or schedule","Add the extra features to the requirements document at the end of each month so that the documents match what has been built","Ask the sponsor for an extra 10 percent of budget so that the team can absorb future requests as they come in from the client"],ans:[0,1],why:["Đúng: mọi yêu cầu mới phải qua change control, so với scope baseline và traceability matrix trước khi làm việc. Như vậy scope creep bị chặn tại nguồn.","Đúng: ghi nhận yêu cầu rồi chuyển cho business analyst, người liên kết từng yêu cầu được duyệt với một requirement, giữ traceability và cho client một kênh rõ ràng thay vì nhờ developer trực tiếp.","Sai: việc nhỏ dưới bốn giờ cộng dồn thành gold plating và scope creep, đồng thời không ai kiểm tra giá trị hay rủi ro. Mọi thay đổi, dù nhỏ, đều phải được phân tích.","Sai: cập nhật tài liệu cho khớp sản phẩm đã làm là làm ngược quy trình, vì yêu cầu phải được duyệt trước khi làm. Cách này che đi việc đã làm ngoài phạm vi.","Sai: xin thêm 10 % ngân sách để hấp thụ yêu cầu tương lai là chấp nhận scope creep, và dự phòng không được xin cho việc chưa phân tích. Nguyên nhân (không có kênh yêu cầu) vẫn còn."],exp:"Task R2 (yêu cầu và phạm vi — requirements, scope): scope baseline được bảo vệ bằng change control và traceability matrix. Mọi yêu cầu bổ sung phải được ghi, phân tích tác động, duyệt rồi mới làm. Quy tắc nhớ: không có yêu cầu được duyệt thì không có việc để làm. Bẫy: coi việc nhỏ là miễn phí, hoặc cập nhật tài liệu sau khi đã làm."}],I=[{id:"o541",n:541,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["predictive","eco-2026","format-2026","matching","stakeholder-grid","engagement"],type:"match",figure:{title:"Power/interest grid after the stakeholder analysis",width:600,height:330,boxes:[{label:"Regulator",sub:"Issues the permits",x:135,y:50,w:200,h:80},{label:"Fleet director",sub:"Owns the budget",x:375,y:50,w:200,h:80},{label:"Shop owners",sub:"Next to the depot",x:135,y:190,w:200,h:80},{label:"Depot drivers",sub:"Will use the system",x:375,y:190,w:200,h:80}],labels:[{text:"High power",x:120,y:95,anchor:"end"},{text:"Low power",x:120,y:235,anchor:"end"},{text:"Low interest",x:235,y:305},{text:"High interest",x:475,y:305}]},q:"A project manager is planning stakeholder engagement for a depot-automation project that follows a predictive plan. The figure shows where four stakeholders sit on the power/interest grid after the analysis. Match each stakeholder to the engagement strategy that fits the stakeholder's place on the grid.",items:["Regulator: has asked only for the safety test certificates to be filed before the depot opens","Depot drivers: have asked how the new routes and shift rota will work once the system is live","Fleet director: wants a say in the choices that affect the budget and the go-live date","Shop owners: sometimes ask about noise and delivery times but cannot influence project decisions"],opts:["Manage closely","Keep satisfied","Keep informed","Monitor"],ans:[1,2,0,3],why:["Keep satisfied: cơ quan cấp phép nằm ở ô quyền lực cao, quan tâm thấp. Họ có thể chặn dự án nên cần được đáp ứng đúng thứ họ cần (chứng chỉ an toàn) đúng lúc, nhưng không cần cập nhật thường xuyên làm họ quá tải.","Keep informed: tài xế ở ô quyền lực thấp, quan tâm cao. Họ không quyết định gì, nhưng cần biết tuyến mới và ca trực sẽ ra sao; thông tin đều đặn giúp họ ủng hộ và cho phản hồi hữu ích khi hệ thống chạy.","Manage closely: giám đốc đội xe ở ô quyền lực cao, quan tâm cao. Người này cần được làm việc sát, cùng tham gia các quyết định về ngân sách và ngày go-live, không chỉ nhận báo cáo cuối tháng.","Monitor: chủ cửa hàng quanh depot ở ô quyền lực thấp, quan tâm thấp. Chỉ cần theo dõi và trả lời khi họ hỏi; dồn nhiều công sức vào nhóm này là lãng phí so với các nhóm còn lại."],exp:'Task P4 "Engage stakeholders": lưới quyền lực/quan tâm chọn mức công sức theo vị trí của từng bên. Quyền lực cao và quan tâm cao: manage closely. Quyền lực cao, quan tâm thấp: keep satisfied. Quyền lực thấp, quan tâm cao: keep informed. Cả hai thấp: monitor. Bẫy: nhầm keep satisfied với keep informed vì cả hai đều là "gửi thông tin", trong khi khác nhau ở chỗ ai có thể chặn dự án.'},{id:"o542",n:542,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["agile","eco-2026","format-2026","matching","quality","definition-of-done"],type:"match",q:"In an agile project that builds a patient-booking app, the project manager reviews the quality practices the team uses. Each practice has a different purpose, and the team faces four separate situations this month. Match each situation to the quality practice that addresses it best.",items:["At every sprint review, people argue whether a story counts as finished, because testing, documentation and security checks are done differently on each story.",'The product owner and the developers disagree whether the "reset password" story is complete, because nobody wrote down what it had to do for this story.',"Every night the team wants to know within minutes whether the day's changes have broken any feature that already worked.","A developer wants a colleague to read a change and look for design flaws before it is merged into the main branch."],opts:["Acceptance criteria","Peer code review","Definition of done","Automated regression tests"],ans:[2,0,3,1],why:['Definition of done: tình huống nói về một chuẩn chung áp dụng cho mọi story (kiểm thử, tài liệu, bảo mật). Thiếu chuẩn chung thì mỗi story được "xong" theo một cách khác nhau và buổi review nào cũng tranh cãi.','Acceptance criteria: đây là điều kiện riêng của một story cụ thể, viết ra trước khi làm để product owner và developer cùng hiểu "đạt" là gì. Definition of done thì chung cho mọi story, không giải quyết được chuyện riêng của story reset password.',"Automated regression tests: chỉ kiểm thử tự động chạy mỗi đêm mới cho câu trả lời trong vài phút về việc thay đổi hôm nay có làm hỏng tính năng cũ không. Review bằng người chậm hơn và không phủ hết các tính năng cũ.","Peer code review: một đồng nghiệp đọc thay đổi trước khi gộp để phát hiện lỗi thiết kế mà test tự động khó thấy. Nó diễn ra trước khi merge, không phải kiểm tra toàn bộ hệ thống mỗi đêm."],exp:'Task R7 "Plan and optimize quality of products/deliverables": mỗi thực hành chất lượng trả lời một câu hỏi khác nhau. Definition of done: chuẩn chung của mọi story. Acceptance criteria: điều kiện riêng của một story. Automated regression tests: có làm hỏng thứ đang chạy không. Peer code review: thiết kế và mã có ổn không trước khi gộp. Bẫy: nhầm acceptance criteria với definition of done, vì cả hai đều nói về "xong".'},{id:"o543",n:543,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","matching","artifacts","expectations"],type:"match",q:"A hybrid project to modernise a company's payroll system has stakeholders who keep asking the project manager similar kinds of questions. The project manager wants to answer each concern with the artifact that was created for it. Match each stakeholder concern to the artifact that answers it best.",items:["The sponsor asks which quarter the reporting features are expected to appear and how the product direction fits the company strategy over the next year.","The operations manager asks on what date the pilot version will be deployed and which features it will contain.","The finance director worries about what could go wrong with the bank data feed and who is responsible for handling it.","A department head asks who may approve a change to the payslip layout and who should only be consulted about it."],opts:["RACI matrix","Product roadmap","Risk register","Release plan"],ans:[1,3,2,0],why:['Product roadmap: câu hỏi của sponsor là hướng sản phẩm trong nhiều quý, mức khái quát. Roadmap trả lời "khi nào khoảng quý nào có giá trị gì", không đi vào ngày triển khai cụ thể của một bản phát hành.',"Release plan: operations cần ngày triển khai pilot và tính năng đi kèm trong bản đó. Đó là nội dung của release plan; roadmap quá khái quát và không chốt ngày hay nội dung từng release.",'Risk register: mối lo "điều gì có thể hỏng và ai xử lý" chính là nội dung của sổ đăng ký rủi ro, gồm rủi ro, người sở hữu và phương án ứng phó.',"RACI matrix: câu hỏi ai phê duyệt (accountable) và ai chỉ được tham vấn (consulted) cho một thay đổi là việc của ma trận vai trò. Các artifact còn lại không phân định quyền quyết định."],exp:'Task P5 "Align stakeholder expectations": kỳ vọng lệch thường vì người hỏi không biết artifact nào chứa câu trả lời. Roadmap: hướng và thời gian ở mức cao. Release plan: ngày và nội dung từng bản phát hành. Risk register: rủi ro, chủ sở hữu, ứng phó. RACI: ai quyết, ai làm, ai được hỏi. Bẫy: dùng roadmap để hứa ngày cụ thể hoặc dùng release plan để bàn hướng sản phẩm dài hạn.'},{id:"o544",n:544,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","matching","hybrid-plan","approach-selection"],type:"match",figure:{title:"Work streams in the integrated plan of the smart-parking project",width:640,height:250,boxes:[{label:"Permits",sub:"City approval first",x:20,y:30,w:180,h:62},{label:"Network cabling",sub:"Design is complete",x:230,y:30,w:180,h:62},{label:"Sensor install",sub:"Dates in contract",x:440,y:30,w:180,h:62},{label:"Mobile app",sub:"Needs still unclear",x:125,y:150,w:180,h:62},{label:"Operator portal",sub:"Feedback each sprint",x:335,y:150,w:180,h:62}],edges:[[0,1],[1,2],[3,4]]},q:"A city council runs a smart-parking project as a hybrid project. The figure shows five work streams that the project manager sketched for the integrated plan. Match each work stream to the approach that suits it best, judging by how well its requirements are known and how often feedback is expected.",items:["Permits: the conditions are fixed by regulation, and the application must be approved before any digging starts.","Mobile app: drivers have never used a parking app, so the team expects to learn what they need from each demo.","Network cabling: the routes were designed by an engineer and priced into a fixed-price contract.","Operator portal: operators will review a working version every two weeks and reprioritise the features.","Sensor install: each of the 400 bays gets the same sensor, delivered on dates written into the supplier contract."],opts:["Predictive","Agile","Hybrid inside the stream"],ans:[0,1,0,1,0],why:["Predictive: điều kiện cấp phép cố định theo quy định và phải xong trước khi đào, nên cần lập kế hoạch đầy đủ từ đầu và kiểm soát bằng baseline. Phản hồi từng sprint không làm thay đổi được điều luật.","Agile: nhu cầu của tài xế chưa rõ và chỉ lộ ra khi họ thấy bản chạy được. Làm từng phần nhỏ, cho xem sau mỗi sprint rồi điều chỉnh sẽ rẻ hơn nhiều so với chốt toàn bộ yêu cầu từ đầu.","Predictive: thiết kế đã hoàn tất và giá cố định trong hợp đồng, nên phạm vi, lịch và chi phí được chốt trước và kiểm soát thay đổi chặt. Không còn điều gì cần khám phá dần.","Agile: người vận hành xem bản chạy mỗi hai tuần và xếp lại ưu tiên, đúng mô hình lặp với backlog thay đổi. Ngược lại, một kế hoạch chốt cứng sẽ cản trở việc nhận phản hồi này.","Predictive: 400 cảm biến giống nhau, ngày giao nằm trong hợp đồng với nhà cung cấp. Công việc lặp lại, đã biết rõ, nên lập kế hoạch và theo dõi tiến độ theo baseline là phù hợp."],exp:'Task R1 "Develop an integrated project management plan and plan delivery": dự án hybrid không chọn một approach cho cả dự án mà chọn theo từng luồng công việc. Yêu cầu đã biết rõ, bị ràng buộc bởi luật hoặc hợp đồng: predictive. Yêu cầu còn khám phá, cần phản hồi thường xuyên: agile. Bẫy: gán agile cho mọi thứ "cho hiện đại", hoặc predictive cho mọi thứ có hợp đồng, bỏ qua mức độ rõ ràng của yêu cầu.'},{id:"o545",n:545,t:0,origin:"original",eco:"B3",domain:"business",approach:"predictive",tags:["predictive","eco-2026","format-2026","matching","change-control","change-log"],type:"match",figure:{title:"Change control process used on the hospital fit-out",width:720,height:170,boxes:[{label:"1 Log request",sub:"Enter in change log",x:15,y:50,w:150,h:70},{label:"2 Assess impact",sub:"Time, cost, risk",x:195,y:50,w:150,h:70},{label:"3 Decide",sub:"Approve or reject",x:375,y:50,w:150,h:70},{label:"4 Update plans",sub:"Baselines, team",x:555,y:50,w:150,h:70}],edges:[[0,1],[1,2],[2,3]]},q:"The project manager of a hospital fit-out uses the change control process shown in the figure on a predictive project. Four things happened this week, each at a different step of the process. Match each event to the step of the process in which it belongs.",items:["After approval, the project manager re-baselines the schedule and cost and tells the contractor and the team.","The scheduler works out that the extra cable run adds 6 days and $18,000 to the project.","A site engineer emails a request to move a wall, and the project manager gives it a number in the change log.","The change control board approves the request on condition that the sponsor funds it from the management reserve."],opts:["Step 1","Step 2","Step 3","Step 4"],ans:[3,1,0,2],why:["Step 4: sau khi được duyệt, PM cập nhật baseline và thông báo cho nhà thầu, đội. Cập nhật kế hoạch chỉ làm sau quyết định, không làm trước khi change được chấp thuận.","Step 2: tính ra tác động +6 ngày và +$18.000 là đánh giá tác động lên thời gian và chi phí. Việc này làm trước khi ban quyết định, để ban có dữ liệu.","Step 1: yêu cầu mới được ghi vào change log và đánh số ngay khi nhận, chưa đánh giá hay duyệt. Mọi yêu cầu, kể cả sẽ bị từ chối, đều phải được ghi lại.","Step 3: change control board ra quyết định duyệt, có điều kiện nguồn tiền. Quyết định thuộc về ban, không phải PM hay người đề xuất."],exp:'Task B3 "Manage and control changes": quy trình kiểm soát thay đổi đi theo thứ tự ghi nhận, đánh giá tác động, quyết định, rồi mới cập nhật kế hoạch và truyền đạt. Quy tắc nhớ: không ai thực hiện thay đổi trước bước quyết định, và baseline chỉ đổi sau khi được duyệt. Bẫy: bắt tay làm hoặc cập nhật baseline ngay khi nhận yêu cầu, hoặc đánh giá tác động khi chưa ghi vào log.'},{id:"o546",n:546,t:0,origin:"original",eco:"P7",domain:"people",approach:"agile",tags:["agile","eco-2026","format-2026","matching","knowledge-transfer","mentoring"],type:"match",q:"Over the next month an agile team loses a contractor and two engineers who move to another programme, and it is onboarding a new tester. The project manager must make sure the knowledge stays in the team. Match each situation to the knowledge-transfer technique that fits it best.",items:["Several teams in the company ask the same questions about the new payment API, and the lead wants one regular open session where anyone can share and learn.","A contractor leaves in two weeks, and the support team needs step-by-step answers to the recurring night-time incidents without having to phone anyone.","A new tester joined and should learn the payment module by working beside the developer who wrote it, on the same stories during the sprint.","Support and development have no view of each other's daily work. To remove this gap, people from the two groups will swap seats for one sprint."],opts:["Written runbook in the wiki","Pairing on the same task","Job rotation between teams","Community of practice talk"],ans:[3,0,1,2],why:["Community of practice talk: buổi chia sẻ mở, định kỳ cho nhiều đội cùng hỏi cùng học đúng là mục đích của community of practice. Wiki thì lưu lại được nhưng không tạo ra buổi trao đổi hai chiều giữa các đội.","Written runbook in the wiki: nhà thầu sắp rời đi và đội hỗ trợ cần tự tra cứu từng bước lúc nửa đêm, nên tri thức phải được viết ra và lưu lại. Mentor hay luân phiên không giúp khi người chuyển giao đã đi.","Pairing on the same task: người mới làm cùng một việc, cùng một story bên cạnh tác giả của module trong cả sprint. Cách này chuyển giao tri thức ngầm qua làm việc song song, không phải qua tài liệu.","Job rotation between teams: hai nhóm đổi chỗ trong một sprint để mỗi bên hiểu công việc hằng ngày của bên kia. Mục tiêu là hiểu biết chéo giữa các nhóm, khác với việc kèm một người mới làm cùng một việc."],exp:'Task P7 "Help ensure knowledge transfer": chọn kỹ thuật theo loại tri thức và hoàn cảnh. Tri thức cần tra cứu khi người giữ đã đi: viết thành tài liệu. Tri thức ngầm: pairing hoặc mentoring. Hiểu công việc của nhóm khác: luân phiên đổi chỗ giữa các nhóm. Chia sẻ rộng giữa nhiều đội: community of practice. Bẫy: chỉ viết tài liệu cho tri thức cần làm thử, hoặc chỉ pairing khi người giữ tri thức sắp rời đi trước khi kịp làm cùng.'},{id:"o547",n:547,t:0,origin:"original",eco:"R4",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","matching","skills-matrix","resource-assignment"],type:"match",figure:{title:"Skills matrix of the shutdown team",width:680,height:262,boxes:[{label:"Level 4",sub:"Ana · Welding",x:112,y:56,w:130,h:52},{label:"Level 2",sub:"Ben · Welding",x:252,y:56,w:130,h:52},{label:"Level 3",sub:"Chi · Welding",x:392,y:56,w:130,h:52},{label:"Level 1",sub:"Dan · Welding",x:532,y:56,w:130,h:52},{label:"Level 2",sub:"Ana · Rigging",x:112,y:116,w:130,h:52},{label:"Level 4",sub:"Ben · Rigging",x:252,y:116,w:130,h:52},{label:"Level 1",sub:"Chi · Rigging",x:392,y:116,w:130,h:52},{label:"Level 3",sub:"Dan · Rigging",x:532,y:116,w:130,h:52},{label:"Level 1",sub:"Ana · PLC code",x:112,y:176,w:130,h:52},{label:"Level 3",sub:"Ben · PLC code",x:252,y:176,w:130,h:52},{label:"Level 4",sub:"Chi · PLC code",x:392,y:176,w:130,h:52},{label:"Level 2",sub:"Dan · PLC code",x:532,y:176,w:130,h:52}],labels:[{text:"Ana",x:177,y:40},{text:"Ben",x:317,y:40},{text:"Chi",x:457,y:40},{text:"Dan",x:597,y:40},{text:"Welding",x:100,y:87,anchor:"end"},{text:"Rigging",x:100,y:147,anchor:"end"},{text:"PLC code",x:100,y:207,anchor:"end"},{text:"Level 4 lead and teach · 3 works alone · 2 needs supervision · 1 beginner",x:12,y:250,anchor:"start"}]},q:"During a plant shutdown on a predictive project, the project manager assigns four tasks to four team members, one task each. The figure shows each person's skill level from 1 to 4. Match each task to the person who should do it, using the skill levels in the figure.",items:["Write the controller logic for the new interlock, the most complex part, which nobody else on the team can check.","Rig the small secondary lift that runs at the same time as the main lift, with no supervisor present.","Lead the rigging crew for the 8-tonne vessel lift and coach the two juniors on the crew.","Weld the vessel supports, which the contractor's inspector says must be done by the team's most experienced welder."],opts:["Ana","Ben","Chi","Dan"],ans:[2,3,1,0],why:["Chi: mức PLC 4 là cao nhất, và việc này cần người dẫn dắt vì không ai kiểm tra được. Ben có PLC 3 chỉ làm được một mình, không đủ cho phần phức tạp nhất mà không ai soát lại.","Dan: Rigging 3 nghĩa là làm một mình được, đủ cho việc phụ không có người giám sát. Ben (4) đã dẫn đội nâng chính, Ana (2) cần giám sát và Chi (1) mới học.","Ben: chỉ Ben có Rigging 4, mức dẫn dắt và dạy người khác, đúng yêu cầu dẫn đội và kèm hai người mới. Dan (3) làm một mình được nhưng chưa ở mức dạy.","Ana: Welding 4 là mức cao nhất đội, đúng yêu cầu của thanh tra. Chi (3) làm được một mình nhưng không phải người giàu kinh nghiệm nhất."],exp:'Task R4 "Plan and manage resources": gán việc theo mức kỹ năng so với đòi hỏi của việc, không theo người rảnh. Mức 4 cho việc cần dẫn dắt hoặc không ai soát lại; mức 3 cho việc làm một mình; mức 2 trở xuống cần giám sát. Với ghép một-một, kiểm cả ràng buộc loại trừ: người đã dẫn đội nâng chính không thể rigging ở lift phụ. Bẫy: giao mọi việc khó cho cùng một người giỏi nhất.'},{id:"o548",n:548,t:0,origin:"original",eco:"B6",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","matching","continuous-improvement","retrospective"],type:"match",q:"A hybrid programme has an agile product team and a predictive construction work stream. The project manager wants the right improvement tool in each of four situations that came up this quarter. Match each situation to the improvement tool that fits it best.",items:["Every two weeks the product team wants to inspect how it worked together and choose one change to try in the next sprint.","A phase closes on the construction stream, and the PMO wants the experience of this phase recorded for use by future projects.","The same sealing defect has returned three times after patches, and the team must find why it keeps happening instead of patching again.","A manager gathers operators and engineers for three days to redesign the packing line, remove waste and test each change at once."],opts:["Root cause analysis","Kaizen event","Retrospective","Lessons learned register"],ans:[2,3,0,1],why:["Retrospective: đội tự xem lại cách làm theo nhịp cố định và chọn một thay đổi cho sprint sau là đúng mục đích và nhịp của retrospective. Nó không dành cho việc ghi kinh nghiệm cho dự án khác.","Lessons learned register: kết thúc một giai đoạn, kinh nghiệm được ghi lại để dự án sau dùng, chính là sổ lessons learned. Retrospective chỉ cải tiến cho chính đội đó ở sprint kế.","Root cause analysis: lỗi lặp lại sau nhiều lần vá cho thấy cần tìm nguyên nhân gốc (ví dụ bằng 5 Whys hoặc fishbone) thay vì xử lý triệu chứng lần nữa.","Kaizen event: ba ngày tập trung với người làm trực tiếp, loại lãng phí và thử ngay từng thay đổi là hình thức kaizen event. Nó khác phân tích nguyên nhân của một lỗi cụ thể."],exp:'Task B6 "Continuous improvement": mỗi công cụ cải tiến có phạm vi và nhịp riêng. Retrospective: định kỳ, cho chính đội, thay đổi nhỏ. Lessons learned register: ghi kinh nghiệm để dùng cho dự án khác. Root cause analysis: tìm nguyên nhân gốc của một vấn đề lặp lại. Kaizen event: đợt ngắn, tập trung, cải tiến một quy trình. Bẫy: nhầm retrospective với lessons learned khi cả hai đều "nhìn lại".'},{id:"o549",n:549,t:0,origin:"original",eco:"P1",domain:"people",approach:"predictive",tags:["predictive","eco-2026","format-2026","matching","project-documents","charter"],type:"match",q:"A project manager joins a predictive project that is about to start and notices that several project documents are being mixed up in meetings. Match each remark made by a stakeholder to the document that contains the information the stakeholder is describing.",items:["The sponsor says the document lists what is in and out of scope, the main deliverables and the criteria for accepting them.","A director asks for the document that gave the project manager formal authority to use the budget and to assign people to the work.","The finance lead wants to see how the benefits will be measured and who will own them after the project has delivered.","The board asks for the document that explained why the investment was worth making, with the problem, the options and the expected return."],opts:["Business case","Benefits management plan","Project charter","Project scope statement"],ans:[3,2,1,0],why:["Project scope statement: tài liệu mô tả cái gì thuộc và không thuộc phạm vi, sản phẩm bàn giao chính và tiêu chí nghiệm thu là scope statement. Charter chỉ nêu mục tiêu và ranh giới ở mức cao.","Project charter: văn bản ủy quyền dự án, trao quyền sử dụng nguồn lực và bổ nhiệm project manager. Business case giải thích vì sao đầu tư nhưng không cấp quyền.","Benefits management plan: kế hoạch nêu lợi ích được đo thế nào, ai sở hữu và thực hiện sau khi dự án bàn giao. Business case chỉ ước tính lợi ích ban đầu.","Business case: lý do đầu tư, vấn đề, các phương án và lợi nhuận kỳ vọng là nội dung của business case, có trước charter và là cơ sở để duyệt dự án."],exp:'Task P1 "Develop a common vision": mỗi tài liệu khởi động trả lời một câu hỏi khác. Business case: vì sao nên đầu tư. Charter: ai được ủy quyền làm gì để bắt đầu. Scope statement: sẽ làm và không làm những gì. Benefits management plan: lợi ích đo và giữ thế nào sau khi giao. Bẫy: nhầm business case với charter khi cả hai nằm trong giai đoạn khởi động và đều nói về mục tiêu.'},{id:"o550",n:550,t:0,origin:"original",eco:"R8",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","pull-down","float","critical-path"],type:"dropdown",exhibit:{title:"Activities of the data-centre move",kind:"table",columns:["Activity","Duration (days)","Predecessor"],rows:[["A",3,"-"],["B",5,"-"],["C",3,"A"],["D",2,"B"],["E",3,"C and D"]],note:"All dependencies are finish-to-start with no lag. Activities A and B can start on day 0."},q:"A project manager reviews the schedule of a data-centre move on a predictive project, using the activity table shown. All dependencies are finish-to-start and there are no lags. Select the option that correctly completes each part of the analysis.",template:"The critical path runs through activities {0}. Activity A has a total float of {1}. If activity A takes 2 days longer than planned, the project finish date moves {2}.",blanks:[["A–C–E","A–D–E","B–D–E","B–C–E"],["0 days","1 day","2 days","3 days"],["by 1 day","by 2 days","by 3 days","by 0 days"]],opts:[],ans:[2,1,0],why:["B–D–E dài 5 + 2 + 3 = 10 ngày, trong khi A–C–E chỉ 3 + 3 + 3 = 9 ngày. Đường găng là đường dài nhất qua mạng, nên là B–D–E. Hai đường còn lại (A–D–E, B–C–E) không có trong bảng phụ thuộc.","A–C–E có 9 ngày so với 10 ngày của đường găng, nên A có total float 10 − 9 = 1 ngày: A có thể trễ 1 ngày mà ngày kết thúc dự án không đổi. Float 0 chỉ có ở hoạt động trên đường găng.","A trễ 2 ngày thì A–C–E dài 3 + 2 + 3 + 3 = 11 ngày, hơn đường găng cũ 1 ngày. Trễ 2 ngày trừ 1 ngày float còn lại 1 ngày, nên dự án trễ đúng 1 ngày, không phải 2."],exp:'Task R8 "Plan and manage schedule": đường găng là đường dài nhất; total float của một hoạt động là thời gian nó có thể trễ mà không làm trễ ngày kết thúc. Cách làm: cộng thời lượng từng đường, lấy hiệu với đường găng; trễ vượt float mới đẩy ngày kết thúc, và đẩy đúng phần vượt. Free float của C ở đây là 1 ngày (E bắt đầu ngày 7, C xong ngày 6). Bẫy: coi mọi trễ của hoạt động ngoài đường găng đều làm trễ dự án.'},{id:"o551",n:551,t:0,origin:"original",eco:"R6",domain:"process",approach:"agile",tags:["agile","eco-2026","format-2026","pull-down","burn-rate","sprint-cost"],type:"dropdown",q:"An agile team has five developers at $1,600 per week each, plus a Scrum Master and a product owner at $2,000 per week each. Sprints last two weeks, and the velocity is a stable 16 points. 64 points remain in the backlog and $100,000 of the budget remains. Select the option that correctly completes each part of the forecast.",template:"The cost of one two-week sprint is {0}. At the current velocity the remaining backlog needs {1}, so the forecast cost to finish is {2}.",blanks:[["$12,000","$16,000","$24,000","$26,000"],["3 sprints","4 sprints","5 sprints","6 sprints"],["$4,000 under the remaining budget","$4,000 over the remaining budget","$24,000 under the remaining budget","$24,000 over the remaining budget"]],opts:[],ans:[2,1,0],why:["Chi phí mỗi tuần là 5 × 1.600 + 2 × 2.000 = $12.000, nên một sprint hai tuần là $24.000. $12.000 chỉ là một tuần, $16.000 bỏ sót Scrum Master và product owner, còn $26.000 cộng sai.","Velocity 16 điểm mỗi sprint, còn 64 điểm nên cần 64 ÷ 16 = 4 sprint. 3 sprint chỉ làm được 48 điểm, còn 5 sprint là quá mức cần thiết.","Chi phí dự báo là 4 × $24.000 = $96.000, thấp hơn ngân sách còn lại $100.000 là $4.000. Hai lựa chọn $24.000 là con số của đúng một sprint, không phải chênh lệch của cả phần việc còn lại."],exp:'Task R6 "Plan and manage finance": trong agile, đội ổn định nên chi phí mỗi sprint gần như cố định. Cách dự báo: chi phí sprint = chi phí tuần × số tuần; số sprint còn lại = điểm còn lại ÷ velocity; chi phí còn lại = số sprint × chi phí sprint, rồi so với ngân sách còn lại. Bẫy: bỏ sót người không code (Scrum Master, product owner) hoặc lấy chi phí tuần làm chi phí sprint.'},{id:"o552",n:552,t:0,origin:"original",eco:"P6",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","pull-down","nps","satisfaction"],type:"dropdown",exhibit:{title:'Pilot survey: "How likely are you to recommend the new system?" (0 to 10)',kind:"table",columns:["Score group","Respondents"],rows:[["Promoters (9–10)",90],["Passives (7–8)",70],["Detractors (0–6)",40]],note:"Total respondents: 200. Net Promoter Score = percent promoters minus percent detractors."},q:"After the pilot of a hybrid project, the project manager surveys 200 pilot users and summarises the answers in the table shown. The sponsor asks what the result means and what the project should do next. Select the option that correctly completes each part of the summary.",template:"The Net Promoter Score of the pilot is {0}. The group that shows the project manager most clearly what to fix is the group of {1}. The best next step is to {2}.",blanks:[["+45","+20","+25","+50"],["detractors","passives","promoters","sponsors"],["tell the sponsor the pilot succeeded because the score is positive, and close the survey","interview a sample of detractors and turn what they say into prioritised backlog items","thank the promoters and repeat the same survey after go-live without further analysis","send the detractors' names to their managers so each manager can follow up alone"]],opts:[],ans:[2,0,1],why:["Promoters là 90 ÷ 200 = 45 %, detractors là 40 ÷ 200 = 20 %, nên NPS = 45 − 20 = +25. +45 chỉ là tỉ lệ promoters, +20 là tỉ lệ detractors, +50 là hiệu số lượng người (90 − 40) chứ không phải phần trăm.","Detractors là nhóm không hài lòng, nên cho biết rõ nhất điều gì sai. Promoters cho biết điều gì đang làm tốt; passives thì thờ ơ, ít tín hiệu cụ thể. Mục đích đọc kết quả là tìm cái cần sửa.",'Phỏng vấn mẫu detractors rồi đưa nguyên nhân vào backlog biến điểm số thành hành động cụ thể, có người ưu tiên và theo dõi. Chỉ báo cáo "điểm dương" hay giao việc cho từng quản lý đều bỏ qua việc học từ phản hồi.'],exp:'Task P6 "Manage stakeholder expectations": đo mức hài lòng chỉ có giá trị khi dẫn tới hành động. NPS = % promoters − % detractors, nằm từ −100 đến +100. Nhóm detractors là nguồn thông tin cải tiến giá trị nhất; bước tiếp theo là hiểu nguyên nhân rồi đưa vào backlog hoặc kế hoạch. Bẫy: coi điểm dương là thành công và dừng, hoặc nhầm NPS với tỉ lệ phần trăm của một nhóm.'},{id:"o553",n:553,t:0,origin:"original",eco:"B5",domain:"business",approach:"agile",tags:["agile","eco-2026","format-2026","pull-down","risk-burndown","risk-adjusted-backlog"],type:"dropdown",exhibit:{title:"Backlog items with business value and risk exposure",kind:"table",columns:["Backlog item","Value (1–10)","Risk exposure (points)"],rows:[["Payment gateway link",8,40],["Report export",3,5],["User login",9,10],["Data import",6,30],["Notifications",2,8]],note:"Risk exposure = probability × impact. Total exposure today: 93 points. Sprint 1 has room for only one of these items."},q:"An agile team building a billing portal keeps a risk-adjusted backlog. The table shows the business value and the risk exposure of five items, and sprint 1 has room for only one of them. The team also tracks total exposure on a risk burndown chart. Select the option that correctly completes each part of the plan.",template:"To learn about the largest uncertainty early without delivering low-value work, the team should start sprint 1 with {0}. If that item is finished and its exposure is fully removed, the total on the risk burndown falls from 93 points to {1}. If the risk burndown stays flat for three sprints, the team should {2}.",blanks:[["User login","Payment gateway link","Data import","Report export"],["53","83","63","40"],["stop tracking the exposure because a flat line shows the risks are stable","add more features to the sprint to use up the capacity the team has left","review the risk responses with the team and replan those that are failing","move every risky item to the end of the backlog until owners report back"]],opts:[],ans:[1,0,2],why:["Payment gateway link vừa có giá trị cao (8) vừa có exposure lớn nhất (40), nên làm sớm vừa giảm rủi ro nhiều nhất vừa tạo giá trị. User login có giá trị cao nhất nhưng exposure chỉ 10, nên không phải ưu tiên giảm bất định.","Tổng exposure còn lại là 93 − 40 = 53 điểm. 83 là kết quả nếu chỉ loại exposure của User login (93 − 10); 63 là nếu chọn Data import (93 − 30); 40 là phần exposure được loại chứ không phải tổng còn lại.","Đường risk burndown phẳng ba sprint nghĩa là các biện pháp ứng phó chưa làm giảm exposure. Việc đúng là cùng đội xem lại biện pháp và lập lại kế hoạch, không phải ngừng theo dõi, thêm việc hay đẩy rủi ro ra cuối."],exp:'Task B5 "Plan and manage risk": backlog điều chỉnh theo rủi ro đưa việc vừa có giá trị vừa bất định cao lên sớm để học nhanh (fail fast). Risk burndown cộng exposure còn lại qua từng sprint; đường dốc xuống là rủi ro đang được xử lý, đường phẳng là biện pháp chưa hiệu quả. Bẫy: chọn việc giá trị cao nhất mà bỏ qua rủi ro, hoặc coi đường phẳng là dấu hiệu ổn định.'},{id:"o554",n:554,t:0,origin:"original",eco:"P3",domain:"people",approach:"predictive",tags:["predictive","eco-2026","format-2026","pull-down","team-development","leadership-style"],type:"dropdown",q:"Three weeks after the kick-off of a predictive systems upgrade, the team of eight, drawn from three departments, openly disagrees about the testing approach, challenges each other's estimates and questions the schedule. All members are motivated and have the skills the work needs, but they still need help to settle their disagreements. The project manager applies Tuckman's model of team development and matches the leadership style to the stage. Select the option that correctly completes each part of the assessment.",template:"The team is in the {0} stage of team development. The leadership style that fits this stage best is {1}. The project manager's most useful action is to {2}.",blanks:[["forming","storming","norming","performing"],["directing","delegating","coaching","transactional"],["facilitate the disagreement, agree decision rules and update the team charter","assign every task personally so that the debates stop and the plan is followed","step back and let the team settle its disputes without any involvement","replace the members who challenge the schedule with more agreeable people"]],opts:[],ans:[1,2,0],why:["Mâu thuẫn công khai về cách làm, thách thức ước tính và lịch là đặc trưng của storming. Forming là lúc lịch sự và còn dè dặt; norming đã có quy tắc chung; performing thì đội tự vận hành trơn tru.","Ở storming, thành viên đã có năng lực nhưng cần giúp quản lý xung đột: coaching vừa hướng dẫn vừa lắng nghe. Directing hợp với forming, delegating hợp với performing, còn transactional (thưởng phạt theo kết quả) không giúp đội giải quyết bất đồng.","Điều hợp cuộc tranh luận, thống nhất quy tắc ra quyết định và cập nhật team charter biến xung đột thành quy tắc làm việc chung. Áp đặt, bỏ mặc hay thay người đều làm mất niềm tin của đội mà không giải quyết nguyên nhân."],exp:'Task P3 "Lead the project team": mô hình Tuckman (forming, storming, norming, performing) cho biết đội đang ở đâu, và kiểu lãnh đạo thay đổi theo giai đoạn: directing, coaching, supporting, delegating. Đội có năng lực nhưng tranh cãi cách làm là storming; PM hỗ trợ giải quyết xung đột và xây quy tắc chung. Bẫy: nghĩ storming là dấu hiệu đội hỏng và phải áp đặt hoặc thay người.'},{id:"o555",n:555,t:0,origin:"original",eco:"R2",domain:"process",approach:"agile",tags:["agile","eco-2026","format-2026","point-and-click","story-map","release-slice"],type:"hotspot",figure:{title:"Story map of the online used-book shop",width:640,height:262,boxes:[{label:"Find a book",sub:"Activity",x:100,y:40,w:160,h:54},{label:"Pay",sub:"Activity",x:274,y:40,w:160,h:54},{label:"Receive order",sub:"Activity",x:448,y:40,w:160,h:54},{label:"Save wish list",sub:"Reader saves titles",x:100,y:112,w:160,h:54},{label:"Card payment",sub:"Pay online by card",x:274,y:112,w:160,h:54},{label:"Live tracking",sub:"Map of the parcel",x:448,y:112,w:160,h:54},{label:"Search by title",sub:"Reader finds a book",x:100,y:184,w:160,h:54},{label:"Instalments",sub:"Pay in 3 parts",x:274,y:184,w:160,h:54},{label:"Shipping label",sub:"Parcel is dispatched",x:448,y:184,w:160,h:54}],labels:[{text:"Activities",x:90,y:72,anchor:"end"},{text:"Stories",x:90,y:178,anchor:"end"}]},q:"A product owner and an agile team are building an online shop for a used-book seller. The story map shows three activities with candidate stories beneath them; the vertical order of the stories is not a ranking. The first release must let a reader complete one purchase from search to delivery with the least work and without staff workarounds. Select the three stories that belong in the first release slice.",opts:[],ans:[4,6,8],why:['Không chọn: "Find a book" là một activity ở hàng trên của story map, không phải story. Câu hỏi yêu cầu chọn story cụ thể nằm bên dưới activity.','Không chọn: "Pay" là tiêu đề activity, không phải một story. Story cần chọn cho activity này nằm ở hàng dưới.','Không chọn: "Receive order" là activity chứ không phải story, nên không thuộc lát cắt phát hành.',"Không chọn: danh sách yêu thích tiện cho độc giả nhưng không cần để hoàn thành một lần mua từ tìm kiếm đến giao hàng, nên để các release sau.","Cần chọn: thanh toán thẻ là cách tối thiểu để hoàn tất đơn mua mà nhân viên không phải xử lý thủ công. Thiếu story này thì luồng mua bị đứt ở bước Pay.","Không chọn: theo dõi bản đồ gói hàng là giá trị gia tăng, nhưng đơn vẫn giao được mà không có nó, nên không thuộc lát cắt mỏng nhất.","Cần chọn: tìm theo tên sách là cách tối thiểu để độc giả tìm được cuốn mình muốn. Không có story này thì luồng mua không bắt đầu được.","Không chọn: trả góp là lựa chọn thanh toán thêm; thanh toán thẻ đã đủ để hoàn tất một lần mua, nên trả góp thuộc các release sau.","Cần chọn: nhãn gửi hàng cần thiết để gói hàng được chuyển đi mà không cần nhân viên viết tay. Thiếu nó thì đơn không đến được người nhận một cách trơn tru."],exp:'Task R2 "Develop and manage project scope": story map đặt activity theo luồng người dùng ở hàng trên và story bên dưới; lát cắt phát hành đầu tiên (walking skeleton) lấy story tối thiểu của mọi activity để luồng chạy từ đầu đến cuối. Quy tắc nhớ: một story cho mỗi activity, đủ để hoàn thành luồng chính. Bẫy: chọn story hấp dẫn (theo dõi, danh sách yêu thích) hoặc chọn thêm nhiều lựa chọn cho cùng một activity.'},{id:"o556",n:556,t:0,origin:"original",eco:"B1",domain:"business",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","point-and-click","governance","approval-authority"],type:"hotspot",figure:{title:"Governance structure of the ticketing-system upgrade",width:640,height:360,boxes:[{label:"Steering committee",sub:"Top decision body",x:235,y:20,w:170,h:50},{label:"Sponsor",sub:"Owns the benefits",x:20,y:110,w:170,h:50},{label:"Change board",sub:"Reviews changes",x:235,y:110,w:170,h:50},{label:"PMO",sub:"Tracks standards",x:450,y:110,w:170,h:50},{label:"Project manager",sub:"Runs the plan",x:20,y:200,w:170,h:50},{label:"Product owner",sub:"Orders the backlog",x:235,y:200,w:170,h:50},{label:"Vendor manager",sub:"Manages the contract",x:450,y:200,w:170,h:50},{label:"Agile team",sub:"Builds the app",x:235,y:290,w:170,h:50},{label:"Install crew",sub:"Fixed-price vendor",x:450,y:290,w:170,h:50}],edges:[[0,1],[0,2],[0,3],[1,4],[4,5],[3,6],[5,7],[6,8]]},q:"A hybrid project to upgrade a ticketing system has the governance structure shown in the figure. The governance plan says: the change board reviews every change and makes a recommendation; any change above $25,000, or any change that moves a contractual milestone, can be approved only by the steering committee; the product owner decides only inside the agreed budget and milestones. A vendor asks for a change that costs $40,000 and moves the vendor-handover milestone by two weeks. The project manager, the PMO and the vendor manager only prepare, track or submit requests. Select the two boxes whose formal decision rights apply to this request: the one that recommends and the one that approves.",opts:[],ans:[0,2],why:["Cần chọn: thay đổi vượt $25.000 và dời mốc hợp đồng, nên chỉ steering committee mới có quyền duyệt theo kế hoạch quản trị. Không có quyết định nào của cấp thấp hơn thay thế được.","Không chọn: sponsor sở hữu lợi ích của dự án nhưng kế hoạch quản trị không trao riêng cho sponsor quyền duyệt thay đổi loại này. Quyền duyệt nằm ở steering committee.","Cần chọn: mọi thay đổi đều phải qua change board để được đánh giá và đưa khuyến nghị lên steering committee. Bỏ qua bước này là bỏ qua quy trình kiểm soát thay đổi.","Không chọn: PMO theo dõi chuẩn mực và báo cáo, không có quyền đánh giá hay duyệt thay đổi của dự án này.","Không chọn: project manager lập và nộp hồ sơ thay đổi nhưng không có thẩm quyền duyệt một thay đổi vượt ngưỡng và dời mốc hợp đồng.","Không chọn: product owner chỉ quyết trong ngân sách và mốc đã thỏa thuận. Thay đổi $40.000 và dời mốc vượt ngoài phạm vi đó.","Không chọn: vendor manager quản lý hợp đồng hằng ngày và có thể trình yêu cầu, nhưng không quyết định việc chấp thuận thay đổi.","Không chọn: đội agile thực hiện công việc theo backlog, không có vai trò phê duyệt thay đổi liên quan đến ngân sách hoặc mốc hợp đồng.","Không chọn: đội lắp đặt của vendor là bên thực hiện, nên không thuộc cơ cấu ra quyết định cho thay đổi này."],exp:'Task B1 "Define and establish project governance": quyền ra quyết định phải được ghi rõ trong kế hoạch quản trị, thường theo ngưỡng chi phí và tác động tới mốc. Một thay đổi vượt ngưỡng cần hai bước: change board đánh giá và khuyến nghị, steering committee duyệt. Quy tắc nhớ: tìm ngưỡng trong đề rồi so với số liệu của yêu cầu. Bẫy: chọn sponsor hoặc product owner vì quen thuộc, dù kế hoạch không trao quyền đó.'},{id:"o557",n:557,t:0,origin:"original",eco:"P4",domain:"people",approach:"agile",tags:["agile","eco-2026","format-2026","point-and-click","stakeholder-engagement","org-chart"],type:"hotspot",figure:{title:"Clinic organisation chart with the roles of each stakeholder",width:700,height:300,boxes:[{label:"Clinic director",sub:"Approved the feature",x:270,y:20,w:160,h:54},{label:"Front desk lead",sub:"Manages reception",x:10,y:120,w:160,h:54},{label:"IT security lead",sub:"Owns privacy rules",x:185,y:120,w:160,h:54},{label:"Finance lead",sub:"Controls the budget",x:360,y:120,w:160,h:54},{label:"Nursing lead",sub:"Runs the wards",x:535,y:120,w:160,h:54},{label:"Receptionists",sub:"Use the desk daily",x:10,y:220,w:160,h:54},{label:"Ward nurses",sub:"Read patient charts",x:535,y:220,w:160,h:54}],edges:[[0,1],[0,2],[0,3],[0,4],[1,5],[4,6]]},q:"An agile team is about to refine the backlog for a feature that replaces paper check-in at a clinic's front desk with a tablet that scans patients' ID cards and stores the scans. The clinic director has already approved the feature and asked the team to work out the details with the people it affects most. The finance lead has confirmed that the feature needs no new budget, and ward nurses never use the check-in step; the nursing lead asked only to be told when it goes live. Select the three stakeholders the project manager should involve first.",opts:[],ans:[1,2,5],why:["Cần chọn: trưởng quầy tiếp tân quản lý quy trình check-in sẽ thay đổi và quyết định cách đội mình dùng tablet. Cần có người này ngay từ lúc làm rõ backlog.","Cần chọn: tablet quét và lưu thẻ ID là dữ liệu cá nhân, nên IT security lead sở hữu quy tắc về quyền riêng tư và có thể chặn hoặc đặt điều kiện cho thiết kế. Nghe sớm tránh phải làm lại.","Không chọn: giám đốc phòng khám đã duyệt tính năng và chủ động ủy quyền việc chi tiết. Không cần họ trong buổi làm rõ đầu tiên.","Không chọn: trưởng tài chính kiểm soát ngân sách đã được duyệt; tính năng này không đổi ngân sách, nên không phải người cần tham gia sớm.","Không chọn: trưởng điều dưỡng quản lý khu bệnh, nơi tính năng không tác động trực tiếp.","Cần chọn: nhân viên tiếp tân là người dùng hằng ngày và biết các tình huống thực tế khi bệnh nhân đăng ký. Phản hồi của họ quyết định tính năng có dùng được không.","Không chọn: điều dưỡng khu bệnh chỉ đọc hồ sơ sau khi bệnh nhân vào khám, không dùng bước check-in. Có thể thông báo sau."],exp:'Task P4 "Engage stakeholders": trong agile, tham gia sớm quan trọng hơn thông báo muộn. Chọn những bên chịu tác động trực tiếp bởi tính năng (người dùng hằng ngày và người quản lý họ) cộng bên có quyền đặt điều kiện (an ninh dữ liệu). Quy tắc nhớ: đọc kỹ tính năng làm gì, rồi tìm ai dùng, ai quản lý, ai có thể chặn. Bẫy: chọn theo chức vụ cao hoặc theo ngân sách khi tính năng không đụng tới họ.'},{id:"o558",n:558,t:0,origin:"original",eco:"R7",domain:"process",approach:"predictive",tags:["predictive","eco-2026","format-2026","point-and-click","root-cause","process-flow"],type:"hotspot",figure:{title:"Production line for modular kitchen units",width:640,height:230,boxes:[{label:"Cut panels",sub:"CNC saw",x:20,y:20,w:170,h:58},{label:"Drill holes",sub:"Fixed drilling jig",x:235,y:20,w:170,h:58},{label:"Edge banding",sub:"Glue and trim",x:450,y:20,w:170,h:58},{label:"Assemble units",sub:"Fit the doors",x:450,y:150,w:170,h:58},{label:"Finish coat",sub:"Spray and dry",x:235,y:150,w:170,h:58},{label:"Final inspection",sub:"Pass or reject",x:20,y:150,w:170,h:58}],edges:[[0,1],[1,2],[2,3],[3,4],[4,5]]},q:"A predictive project assembles modular kitchen units on a factory line, shown in the figure. Last month final inspection rejected 40 of 500 units: 31 had doors that did not line up, 6 had chipped edges and 3 had a scratched finish. Measurements taken straight after the drilling step, before any assembly, already showed the hinge positions 3 mm off the drawing on all 31 units, while the cut panels were within tolerance. Select the process step where the root cause most likely sits.",opts:[],ans:[1],why:["Không chọn: số đo cho thấy các tấm đã cắt đúng dung sai, nên cắt không phải nguyên nhân gây lệch cửa.","Cần chọn: vị trí bản lề lệch 3 mm so với bản vẽ ở cả 31 đơn vị lỗi, và bản lề do bước khoan đặt vị trí. Lệch giống nhau ở mọi đơn vị cho thấy gốc nằm ở jig hoặc cài đặt khoan.","Không chọn: dán cạnh chỉ liên quan 6 đơn vị bị mẻ cạnh, ít hơn nhiều và khác loại lỗi so với nhóm chính 31 đơn vị.","Không chọn: lắp ráp là nơi lỗi lộ ra (cửa không thẳng hàng), nhưng số đo ngay sau bước khoan đã cho thấy lệch trước khi lắp. Sửa ở đây chỉ xử lý triệu chứng.","Không chọn: lớp hoàn thiện chỉ gắn với 3 đơn vị bị xước, một lỗi nhỏ và không liên quan đến lệch bản lề.","Không chọn: kiểm tra cuối là nơi phát hiện lỗi chứ không tạo ra lỗi. Kiểm tra không phải nguyên nhân gốc."],exp:'Task R7 "Plan and optimize quality of products/deliverables": tìm nguyên nhân gốc là lần theo dữ liệu về phía trước dòng chảy, tới bước đầu tiên làm ra sai lệch, không dừng ở nơi lỗi bị phát hiện. Ở đây số liệu (31 trên 40 lỗi, bản lề lệch 3 mm, panel đúng dung sai) chỉ về bước khoan. Quy tắc nhớ: lỗi lộ ra ở bước nào chưa chắc đã phát sinh ở bước đó. Bẫy: chọn bước lắp ráp hoặc kiểm tra cuối.'},{id:"o559",n:559,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","point-and-click","closure","handover"],type:"hotspot",figure:{title:"Steps proposed for the closure checklist (not in time order)",width:640,height:240,boxes:[{label:"Ops handover",sub:"To the service desk",x:235,y:150,w:170,h:58},{label:"Final acceptance",sub:"Sponsor signs off",x:450,y:30,w:170,h:58},{label:"Close contracts",sub:"Vendors, no claims",x:20,y:150,w:170,h:58},{label:"Hypercare",sub:"First 30 days live",x:20,y:30,w:170,h:58},{label:"Next release plan",sub:"Phase 2 backlog",x:450,y:150,w:170,h:58},{label:"Benefits review",sub:"6 months after",x:235,y:30,w:170,h:58}]},q:"A hybrid project has delivered its last release, and the sponsor asks which steps must be finished before the project can be formally closed. The closure plan says: hypercare, the first 30 days of live support, is run by operations under its own plan; the benefits owner runs the benefits review six months later; the product team plans the next release after the project closes. Select the three steps that must be done before the project is closed.",opts:[],ans:[0,1,2],why:["Cần chọn: bàn giao cho vận hành (kèm tài liệu, đào tạo, quyền truy cập) là điều kiện để đóng dự án. Chưa bàn giao thì dự án chưa giao được kết quả vào hoạt động.","Cần chọn: sponsor ký nghiệm thu cuối xác nhận sản phẩm bàn giao đáp ứng tiêu chí chấp thuận. Không có nghiệm thu thì không thể đóng dự án.","Cần chọn: đóng hợp đồng với nhà cung cấp (thanh toán xong, không còn khiếu nại) là việc đóng dự án phải làm trước khi đóng chính thức.","Không chọn: theo kế hoạch đóng, hypercare do bộ phận vận hành chạy theo kế hoạch riêng của họ, nên không nằm trong phạm vi các việc dự án phải hoàn tất.","Không chọn: kế hoạch bản phát hành tiếp theo thuộc đội sản phẩm sau khi dự án đã đóng, nên không phải điều kiện đóng.","Không chọn: đánh giá lợi ích diễn ra sáu tháng sau và do người sở hữu lợi ích thực hiện, ngoài thời điểm đóng dự án."],exp:'Task R10 "Manage project closure": đóng dự án đòi hỏi bàn giao cho vận hành, nghiệm thu cuối và đóng hợp đồng, cùng các việc hành chính như tổng hợp bài học. Những việc do bên khác sở hữu hoặc diễn ra sau đó (hypercare của vận hành, đánh giá lợi ích, kế hoạch bản phát hành mới) không chặn việc đóng. Quy tắc nhớ: hỏi "ai sở hữu và khi nào". Bẫy: kéo dài dự án để chờ các việc hậu dự án.'},{id:"o560",n:560,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["hybrid","eco-2026","format-2026","point-and-click","communication-channels","time-zones"],type:"hotspot",figure:{title:"Communication channels between the four teams",width:710,height:322,boxes:[{label:"Product owner",sub:"Austin",x:10,y:36,w:150,h:58},{label:"QA team",sub:"Berlin",x:10,y:140,w:150,h:58},{label:"Vendor",sub:"Payment API",x:10,y:244,w:150,h:58},{label:"Backlog sync",sub:"Daily 15-min call",x:280,y:36,w:150,h:58},{label:"Defect feed",sub:"Weekly email",x:280,y:140,w:150,h:58},{label:"Change notice",sub:"Ad hoc messages",x:280,y:244,w:150,h:58},{label:"Dev team",sub:"Manila",x:550,y:140,w:150,h:58}],edges:[[0,3],[1,4],[2,5],[3,6],[4,6],[5,6]],labels:[{text:"Teams",x:85,y:20},{text:"Channels",x:355,y:20},{text:"Receiver",x:625,y:20}]},q:"A hybrid project to launch a retail app involves four teams in three time zones: the product owner in Austin, developers in Manila, testers in Berlin and a vendor that maintains the payment API. Developers report that defects found by Berlin reach them about four days after the fact, and twice the vendor changed the API without warning and the build broke. The product owner says her questions to the developers are answered the same day. Select the channels that are not working for the teams.",opts:[],ans:[4,5],why:["Không chọn: Product owner là một đội, không phải kênh. Đề hỏi kênh giao tiếp đang hỏng, và phản hồi của product owner được trả lời trong ngày.","Không chọn: QA team là một đội, không phải kênh. Vấn đề của họ nằm ở kênh chuyển lỗi sang đội phát triển, không ở chính đội.","Không chọn: Vendor là một bên, không phải kênh. Sự cố là vendor đổi API mà không có kênh báo trước đáng tin cậy.","Không chọn: buổi trao đổi backlog 15 phút mỗi ngày đang hoạt động tốt, vì product owner nói câu hỏi được trả lời trong ngày.","Cần chọn: email hằng tuần là kênh quá chậm cho lỗi cần xử lý, nên lỗi tới tay đội phát triển sau bốn ngày. Kênh này cần nhịp nhanh hơn, ví dụ báo lỗi trong công cụ chung hoặc cuộc gọi ngắn lệch giờ.","Cần chọn: tin nhắn tùy hứng không bảo đảm vendor báo trước khi đổi API, nên bản build đã vỡ hai lần. Cần kênh chính thức và quy tắc báo thay đổi có thời hạn.","Không chọn: Dev team là bên nhận, không phải kênh. Vấn đề nằm ở kênh chuyển thông tin tới họ."],exp:'Task P8 "Plan and manage communication": đánh giá hiệu quả của kênh bằng bằng chứng về độ trễ và sự cố, không bằng việc kênh có tồn tại hay không. Ở đây hai kênh có dấu hiệu hỏng: lỗi tới chậm bốn ngày vì dùng email hằng tuần, và vendor thay đổi API mà không có thông báo chính thức. Quy tắc nhớ: kênh phải khớp với tốc độ cần thiết của thông tin và múi giờ của người nhận. Bẫy: chọn các đội thay vì kênh, hoặc sửa kênh đang hoạt động tốt.'}],W=[{id:"c1",title:"Case 1 · Clinic scheduling rollout",text:`A regional healthcare provider is replacing the patient-scheduling system in its 14 clinics. The project uses a hybrid approach. Network hardware is installed by a vendor on fixed dates under a predictive plan, and the pilot go-live for 3 clinics is a milestone in the integrated schedule baseline. The scheduling software is built by one agile team in two-week sprints, and the pilot release is due at the end of sprint 8.

The team has just finished sprint 5. The clinic operations director, who sponsors the pilot, told the steering committee last week that every requested feature will be live in the pilot clinics. Clinic managers keep sending new requests to the product owner, who adds most of them to the release backlog.`,exhibit:{title:"Pilot release burn-up after sprint 5",kind:"line",unit:"story points",columns:["Sprint","Total release scope","Completed"],rows:[["S1",200,18],["S2",200,40],["S3",215,60],["S4",230,78],["S5",245,95]],note:"Sprints 6 to 8 remain before the pilot release."}}],K=[{id:"c2",title:"Case 2 · City library app",text:`A city council is building a mobile app for its 12 branch libraries so that residents can search the catalogue, renew loans and reserve meeting rooms. One agile team of seven (five developers, a tester and a designer) works in two-week sprints. The project manager acts as the team's servant leader, and a librarian from the central branch is the product owner. The first public release is planned for the end of sprint 6.

The team is in sprint 4 and the backlog has grown to 40 items. Two senior developers, Linh and Marcus, hold different views on how strict code reviews should be, and stories have been waiting in the "In review" column of the board for several days. The council's digital services director wants a short update on the release next week.`},{id:"c3",title:"Case 3 · Hospital surgical wing",text:`A hospital trust is fitting out a new surgical wing under a predictive plan with an approved scope baseline and a project budget of $9.6 million. The medical gas, electrical and ventilation installation is let to one installation contractor under a firm fixed-price contract of $4.2 million, and the contractor is paid according to the percentage of each work package that has been completed and verified on site. The trust has set aside $480 thousand for risks that are already listed in the risk register, and any use of it must go through the change control process.

It is now the end of month 6 of a 12-month schedule. The trust's clinical director has asked for a larger recovery room, which would change the electrical and ventilation work that is already in progress. The installation contractor says that rising copper prices are squeezing its margin on the fixed price.`,exhibit:{title:"Installation contract progress at the end of month 6",kind:"table",unit:"$ thousand and percent",columns:["Work package","Contract value ($k)","Planned complete (%)","Verified complete (%)","Invoiced to date ($k)"],rows:[["Medical gas piping",1200,60,60,720],["Electrical distribution",1500,70,50,1050],["Theatre ventilation",900,50,30,270],["Nurse-call and data cabling",600,40,40,240]],note:"Firm fixed price: $4.2 million in total. Percent complete is verified on site by the trust's clerk of works. The latest invoices are included and await approval."}},{id:"c4",title:"Case 4 · AI claims triage",text:`A mid-sized insurer is building an AI tool that scores incoming motor claims and sends each one either to fast-track settlement or to a human adjuster. The project is hybrid. A data science team trains and tunes the model in two-week sprints, while the integration with the claims system and the data-centre changes follow a predictive plan with fixed dates. The tool goes live in three regions at the end of month 9. The model is trained on five years of historic claims, including policyholders' names, addresses and health notes from injury claims.

The insurer operates under its national data protection regulator and employs a privacy officer. The head of claims wants most simple claims settled within two days, and the product owner has asked the data science team to move fast. To speed up experiments, the team was given a full copy of the historic claims in a shared cloud workspace in month 2.`},{id:"c5",title:"Case 5 · University service desk",text:`A university's IT service desk of nine people handles requests from about 6,000 students and staff. After a series of complaints, the head of IT service started an improvement initiative, and the team now manages its work on a Kanban board with the columns Backlog, Analysis, In progress, User reply, Testing and Done. The team agreed work-in-progress (WIP) limits for the four middle columns three months ago. The project manager supports the team as flow coach and reports to the head of IT service.

The head of IT service has set a target of resolving requests in eight working days on average and reviews a utilisation report every Friday. The chart shows the first eight weeks of the improvement initiative.`,exhibit:{title:"Average cycle time and weekly throughput, weeks 1 to 8",kind:"line",unit:"days / items per week",columns:["Week","Average cycle time (days)","Items finished per week"],rows:[["W1",6,10],["W2",6,10],["W3",7,10],["W4",8,10],["W5",9,10],["W6",10,10],["W7",11,10],["W8",12,10]],note:"Cycle time runs from the day work starts on a request to the day it is resolved. Target: 8 working days on average (5 working days per week). WIP limits: Analysis 3, In progress 4, User reply 3, Testing 2, which is 12 in total."}},{id:"c6",title:"Case 6 · Solar panels on school roofs",text:`A school district is installing rooftop solar panels on 12 school buildings under a predictive plan. An installation contractor mounts the panels and wires the inverters. The district's facilities team of four technicians will operate and maintain the systems once the project closes. The district's sustainability goal is to cut grid electricity use at the schools by 30 percent, and its waste and recycling policy requires old roofing material to be recycled where possible. The district's project management office keeps a repository of lessons learned and project templates.

Installation is complete at 11 schools and acceptance tests have passed there; school 12 is finishing. The contractor's crew leaves the district in three weeks, and the contractor's final payment is tied to the sponsor's signed acceptance. The sponsor wants the project closed before the fiscal year ends.`}],E=Object.assign({"./formats/q-501-506.json":C,"./formats/q-507-521.json":j,"./formats/q-522-540.json":M,"./formats/q-541-560.json":I}),D=Object.assign({"./formats/cases-c1.json":W,"./formats/cases-c2-c6.json":K}),h=Object.values(E).flat().sort((n,t)=>n.n-t.n),F=new Map(Object.values(D).flat().map(n=>[n.id,n])),U=n=>h.filter(t=>t.caseId===n),$=Object.freeze([...S,...B]),i=Object.freeze([...A,...$,...h].sort((n,t)=>n.n-t.n));new Map(i.map(n=>[n.id,n]));const z=new Map(i.map(n=>[n.n,n])),G=n=>`${R}&t=${n}s`,X={people:.33,process:.41,business:.26},Y={people:"People",process:"Process",business:"Business Environment"},J="https://www.pmi.org/-/media/pmi/documents/public/pdf/certifications/new-pmp-examination-content-outline-2026.pdf?rev=af7ae1c6006f43009fee4f613a350f9b",a=[{id:"P1",domain:"people",title:"Develop a common vision",focus:"Tầm nhìn chung và nguyên nhân hiểu sai mục tiêu",lab:"Viết một câu tầm nhìn; hỏi hai bên liên quan diễn giải lại và tìm điểm lệch."},{id:"P2",domain:"people",title:"Manage conflicts",focus:"Nguồn gốc xung đột, quy tắc chung và cách giải quyết",lab:"Phân biệt lập trường với lợi ích thật của hai bên; chọn cách hòa giải."},{id:"P3",domain:"people",title:"Lead the project team",focus:"Trao quyền, vai trò, động lực và phong cách lãnh đạo",lab:"Chọn một tình huống đội mất động lực; viết bước đầu tiên của PM."},{id:"P4",domain:"people",title:"Engage stakeholders",focus:"Nhận diện, phân tích và tạo sự tin tưởng với stakeholder",lab:"Lập bản đồ influence × interest cho ba stakeholder trong dự án của bạn."},{id:"P5",domain:"people",title:"Align stakeholder expectations",focus:"Làm rõ và thống nhất kỳ vọng",lab:"Ghi hai kỳ vọng mâu thuẫn rồi thiết kế buổi trao đổi để thống nhất."},{id:"P6",domain:"people",title:"Manage stakeholder expectations",focus:"Theo dõi mức hài lòng của khách hàng và điều chỉnh",lab:"Định nghĩa tín hiệu sớm cho kỳ vọng không còn được đáp ứng."},{id:"P7",domain:"people",title:"Help ensure knowledge transfer",focus:"Tri thức quan trọng, bàn giao và học hỏi",lab:"Thiết kế checklist bàn giao khi chuyên gia chủ chốt rời dự án."},{id:"P8",domain:"people",title:"Plan and manage communication",focus:"Chiến lược, kênh, phản hồi và báo cáo",lab:"Thiết kế thông điệp khác nhau cho sponsor, đội và khách hàng."},{id:"R1",domain:"process",title:"Develop an integrated project management plan and plan delivery",focus:"Cách tiếp cận, kế hoạch tích hợp và phụ thuộc",lab:"Chọn predictive, agile hay hybrid cho một dự án và nêu ba lý do."},{id:"R2",domain:"process",title:"Develop and manage project scope",focus:"Yêu cầu, phạm vi, phân rã và sự đồng thuận",lab:"Viết ranh giới in/out và phân rã một deliverable thành WBS hoặc backlog."},{id:"R3",domain:"process",title:"Help ensure value-based delivery",focus:"Ưu tiên giá trị, feedback và lợi ích",lab:"Xếp hạng ba hạng mục theo giá trị, rủi ro và thời gian tạo giá trị."},{id:"R4",domain:"process",title:"Plan and manage resources",focus:"Nhu cầu, năng lực và sự sẵn có của nguồn lực",lab:"Lập phương án khi một kỹ năng then chốt thiếu trong hai sprint."},{id:"R5",domain:"process",title:"Plan and manage procurement",focus:"Nhà cung cấp, hợp đồng và hiệu quả thực hiện",lab:"So sánh fixed-price và time-and-materials cho một phạm vi chưa rõ."},{id:"R6",domain:"process",title:"Plan and manage finance",focus:"Ước lượng, ngân sách, dự phòng và sai lệch",lab:"Tách contingency reserve khỏi management reserve trong một ví dụ."},{id:"R7",domain:"process",title:"Plan and optimize quality of products/deliverables",focus:"Tiêu chí chất lượng, kiểm soát và cải tiến",lab:"Viết acceptance criteria và cách kiểm tra chất lượng cho một deliverable."},{id:"R8",domain:"process",title:"Plan and manage schedule",focus:"Ước lượng, phụ thuộc, baseline và sai lệch tiến độ",lab:"Vẽ ba công việc phụ thuộc; tìm tác động khi công việc giữa trễ."},{id:"R9",domain:"process",title:"Evaluate project status",focus:"Chỉ số, artifact và báo cáo tình trạng",lab:"Chọn ba chỉ số để báo cáo sức khỏe dự án, nêu quyết định từ mỗi chỉ số."},{id:"R10",domain:"process",title:"Manage project closure",focus:"Chấp thuận, chuyển giao và đóng dự án",lab:"Viết checklist bàn giao sản phẩm sang vận hành."},{id:"B1",domain:"business",title:"Define and establish project governance",focus:"Quyền quyết định, ngưỡng escalations và thành công",lab:"Vẽ đường ra quyết định khi thay đổi vượt ngưỡng ngân sách."},{id:"B2",domain:"business",title:"Plan and manage project compliance",focus:"Luật, bảo mật, an toàn và bền vững",lab:"Liệt kê hai yêu cầu tuân thủ và bằng chứng xác nhận cho mỗi yêu cầu."},{id:"B3",domain:"business",title:"Manage and control changes",focus:"Đánh giá, phê duyệt và triển khai thay đổi",lab:"Vẽ luồng request → impact → approval → update → communicate."},{id:"B4",domain:"business",title:"Remove impediments and manage issues",focus:"Trở ngại, vấn đề đã xảy ra và ưu tiên xử lý",lab:"Tách risk khỏi issue trong một tình huống và chọn hành động đầu tiên."},{id:"B5",domain:"business",title:"Plan and manage risk",focus:"Nhận diện, phân tích, ứng phó và giám sát rủi ro",lab:"Viết risk trigger, owner và response cho một rủi ro thật."},{id:"B6",domain:"business",title:"Continuous improvement",focus:"Lessons learned và cải tiến quy trình",lab:"Biến một bài học thành thay đổi cụ thể của quy trình/OPA."},{id:"B7",domain:"business",title:"Support organizational change",focus:"Văn hóa, mức sẵn sàng và chấp nhận thay đổi",lab:"Lập kế hoạch hỗ trợ một nhóm chống lại cách làm mới."},{id:"B8",domain:"business",title:"Evaluate external business environment changes",focus:"Thị trường, công nghệ, địa chính trị và luật mới",lab:"Chọn một thay đổi bên ngoài; đánh giá ảnh hưởng tới backlog và business case."}],L=new Map(a.map(n=>[n.id,n])),Z={P1:["Thu thập góc nhìn","Viết tầm nhìn chung","Xác nhận lại định kỳ"],P2:["Nghe từng bên","Tìm lợi ích gốc","Thống nhất cách giải quyết"],P3:["Đánh giá đội","Chọn cách lãnh đạo","Trao quyền và phản hồi"],P4:["Nhận diện","Phân tích nhu cầu","Tương tác và theo dõi"],P5:["Làm rõ kỳ vọng","Tìm điểm lệch","Chốt cam kết chung"],P6:["Đo mức hài lòng","Phát hiện lệch kỳ vọng","Điều chỉnh và xác nhận"],P7:["Xác định tri thức","Chuyển giao có kiểm chứng","Lưu và tái sử dụng"],P8:["Ai cần biết gì?","Chọn kênh và nhịp","Nhận phản hồi"],R1:["Đánh giá bối cảnh","Chọn approach","Tích hợp và cập nhật kế hoạch"],R2:["Thu thập yêu cầu","Định ranh giới","Phân rã và xác nhận"],R3:["Xác định giá trị","Ưu tiên và giao sớm","Đo lợi ích thực"],R4:["Dự báo nhu cầu","Cân đối năng lực","Tối ưu phân bổ"],R5:["Quyết định mua hay làm","Chọn hợp đồng/nhà cung cấp","Theo dõi cam kết"],R6:["Ước lượng chi phí","Lập ngân sách/dự phòng","Theo dõi sai lệch"],R7:["Đặt tiêu chí","Kiểm tra chất lượng","Sửa lỗi và cải tiến"],R8:["Ước lượng/phụ thuộc","Chốt lịch phù hợp","Theo dõi sai lệch"],R9:["Chọn chỉ số","Đọc tình trạng thật","Báo cáo và quyết định"],R10:["Xác nhận chấp thuận","Bàn giao vận hành","Đóng và lưu bài học"],B1:["Xác định quyền hạn","Đặt ngưỡng quyết định","Theo dõi governance"],B2:["Xác định nghĩa vụ","Lập bằng chứng tuân thủ","Kiểm tra và khắc phục"],B3:["Ghi nhận yêu cầu","Đánh giá và phê duyệt","Cập nhật rồi truyền đạt"],B4:["Ghi nhận blocker/issue","Ưu tiên tác động","Gỡ vướng và xác nhận"],B5:["Nhận diện risk","Phân tích và ứng phó","Giám sát trigger"],B6:["Rút bài học","Thay đổi cách làm","Đo hiệu quả cải tiến"],B7:["Đánh giá văn hóa","Hỗ trợ chấp nhận","Theo dõi mức áp dụng"],B8:["Quét môi trường ngoài","Đánh giá tác động","Điều chỉnh backlog/kế hoạch"]},nn={P1:{principle:"Tầm nhìn chung trả lời dự án tạo giá trị gì và cho ai. PM phải xác nhận các nhóm đang hiểu cùng một kết quả, không chỉ cùng nghe một thông điệp.",trap:"Đừng vội tổ chức workshop giải pháp khi chưa rõ nguồn gốc hiểu sai."},P2:{principle:"Xung đột cần được hiểu theo bối cảnh và lợi ích thật của các bên. Ưu tiên đối thoại, ground rules và phương án được các bên chấp nhận.",trap:"Leo thang hoặc ép một bên nhượng bộ quá sớm thường bỏ qua nguyên nhân."},P3:{principle:"Phong cách lãnh đạo tùy độ trưởng thành đội và bối cảnh. PM tạo điều kiện, làm rõ vai trò và trao quyền quyết định phù hợp.",trap:"“Trao quyền” không có nghĩa PM tự chỉ định một người quyết thay cả đội."},P4:{principle:"Stakeholder khác nhau về ảnh hưởng, quan tâm và kỳ vọng. Engagement là quan hệ hai chiều cần được điều chỉnh theo phản hồi.",trap:"Cập nhật kế hoạch trên giấy không thay thế việc gặp và lắng nghe người đang lo ngại."},P5:{principle:"Kỳ vọng phải được nói rõ, so sánh và thống nhất trước khi trở thành cam kết. Điều quan trọng là hiểu điểm lệch giữa các nhóm.",trap:"Đừng ngầm coi việc đã gửi tài liệu là mọi stakeholder đã đồng ý."},P6:{principle:"Theo dõi sự hài lòng của khách hàng trong suốt dự án, kể cả khi phạm vi vẫn đúng. Kết quả cần tiếp tục khớp nhu cầu thực.",trap:"“Đúng scope” không tự động có nghĩa khách hàng còn thấy giá trị."},P7:{principle:"Tri thức then chốt cần được xác định sớm, chuyển giao có kiểm chứng và lưu ở nơi đội còn dùng được sau khi người giữ kiến thức rời đi.",trap:"Một thư mục tài liệu không đủ nếu người nhận chưa thể áp dụng tri thức."},P8:{principle:"Kế hoạch giao tiếp xác định ai cần thông tin nào, qua kênh nào, tần suất nào và cách nhận phản hồi.",trap:"Gửi thật nhiều email không đồng nghĩa thông tin đã tới đúng người và được hiểu."},R1:{principle:"Kế hoạch tích hợp gắn mục tiêu, approach, phụ thuộc, nguồn lực và cách kiểm soát thành một hệ thống có thể cập nhật.",trap:"Không chọn agile chỉ vì mới; chọn approach theo độ rõ yêu cầu, rủi ro và nhu cầu feedback."},R2:{principle:"Scope bắt đầu từ yêu cầu, ranh giới và sự đồng thuận; sau đó phân rã thành deliverable hoặc backlog có thể quản lý.",trap:"Đừng nhận thay đổi thêm chỉ vì nghe có ích mà chưa xét phạm vi và thẩm quyền."},R3:{principle:"Ưu tiên theo giá trị mà stakeholder nhận được, đưa ra phần giá trị sớm khi hợp lý và đo lợi ích thực tế, không chỉ đo output.",trap:"Nhiều tính năng hoặc làm xong đúng hạn không bảo đảm tạo business value."},R4:{principle:"Nguồn lực gồm con người, kỹ năng và vật tư cần đúng thời điểm. PM phải cân bằng nhu cầu với khả năng sẵn có.",trap:"Đẩy thêm việc cho thành viên đang quá tải không phải là tối ưu nguồn lực."},R5:{principle:"Procurement đi từ nhu cầu mua, cách lựa chọn hợp đồng/nhà cung cấp đến theo dõi kết quả theo thỏa thuận.",trap:"Đừng chọn loại hợp đồng trước khi hiểu mức chắc chắn của phạm vi và phân chia rủi ro."},R6:{principle:"Kế hoạch tài chính gồm ước lượng, baseline, dự phòng và theo dõi sai lệch để ra quyết định trước khi vượt ngưỡng.",trap:"Không dùng management reserve như khoản PM tự ý rút để chữa mọi phát sinh."},R7:{principle:"Chất lượng được xây vào tiêu chí và quy trình, rồi kiểm tra deliverable và sửa nguyên nhân lỗi để ngăn lặp lại.",trap:"Chỉ kiểm tra ở cuối không thay cho phòng ngừa và cải tiến quá trình."},R8:{principle:"Lịch dự án dựa trên ước lượng và phụ thuộc, có baseline thích hợp; sai lệch phải được phân tích trước khi nén lịch.",trap:"Fast-tracking hoặc crashing ngay khi thấy trễ có thể tăng rủi ro/chi phí không cần thiết."},R9:{principle:"Project status cần bằng chứng từ metrics và artifacts phù hợp, đủ để sponsor và đội ra quyết định.",trap:"Báo cáo “đang ổn” khi chưa kiểm tra tác động thực là tạo cảm giác an toàn giả."},R10:{principle:"Đóng dự án cần xác nhận chấp thuận, sẵn sàng chuyển giao, hoàn tất hợp đồng/tài chính và lưu bài học.",trap:"Giao sản phẩm không đồng nghĩa vận hành đã sẵn sàng tiếp nhận."},B1:{principle:"Governance xác định ai quyết, quyết khi nào, theo ngưỡng nào và đo thành công bằng gì.",trap:"Không tự quyết thay đổi vượt thẩm quyền chỉ vì có vẻ khẩn cấp."},B2:{principle:"Tuân thủ bắt đầu từ xác định nghĩa vụ, đánh giá mức ảnh hưởng và chuẩn bị bằng chứng thực hiện.",trap:"Không trì hoãn yêu cầu pháp lý/bảo mật đến cuối dự án hoặc coi đó là tùy chọn backlog."},B3:{principle:"Thay đổi cần được ghi nhận, phân tích tác động, phê duyệt đúng quyền, rồi cập nhật baseline/backlog và truyền đạt.",trap:"Yêu cầu từ người có chức vụ cao vẫn không bỏ qua change control phù hợp."},B4:{principle:"Issue là vấn đề đã xảy ra; impediment chặn tiến độ hiện tại. PM ưu tiên theo tác động và gỡ vướng cùng người liên quan.",trap:"Đừng chỉ ghi issue log mà không có owner, hành động và kiểm tra kết quả."},B5:{principle:"Risk còn bất định, nên cần trigger, owner, xác suất/tác động và response; khi xảy ra phải quản lý như issue.",trap:"Đừng đợi rủi ro xảy ra mới bắt đầu nghĩ phương án ứng phó."},B6:{principle:"Lessons learned phải chuyển thành thay đổi cách làm/OPA, được thử và đo xem kết quả có tốt hơn không.",trap:"Họp retrospective rồi lưu biên bản mà không đổi gì thì chưa phải continuous improvement."},B7:{principle:"Thay đổi tổ chức tác động đến hành vi và văn hóa, không chỉ quy trình. PM cần đánh giá mức sẵn sàng và hỗ trợ adoption.",trap:"Đào tạo một lần không đủ nếu động cơ và trở ngại áp dụng chưa được xử lý."},B8:{principle:"Theo dõi luật, thị trường, công nghệ và yếu tố ngoài tổ chức; đánh giá tác động lên business case, scope và backlog.",trap:"Không giữ nguyên kế hoạch cũ khi giả định kinh doanh nền tảng đã thay đổi."}},_=["P2","P3","P4","P5","R8","R7","R2","P3","P3","R8","R1","P3","P8","P8","P7","B2","R2","P3","P6","P8","R3","R2","P1","B5","R1","B7","R10","R6","P8","R2","B4","P4","P7","R8","R3","B4","P8","R8","R8","P3","P4","R8","P2","B3","P3","P3","R7","P3","B5","B2","R3","B2","P3","P7","P3","B3","P4","B2","B4","R8","R9","B2","R6","P2","B5","R3","R3","R9","R9","B5","R7","R7","R7","R3","B2","R6","R6","R9","P3","R1","R4","B7","R3","R8","B8","R3","P2","B3","P4","P8","P3","R2","P3","R3","P7","P8","B5","R3","R7","R3","B1","R7","B3","R1","P4","P3","P3","P3","R3","B3","B3","R2","P3","P8","R2","R3","P3","R2","R5","P8","P2","B4","R5","B5","P2","P8","R2","P2","P8","P4","R2","B2","P8","P3","R2","B5","P3","R6","B3","P3","B7","B2","R5","R9","P2","P3","B7","P3","P8","B3","P4","P3","P8","P3","P8","B2","R8","P2","P3","B8","P3","B3","B5","R10","P1","R3","R4","P3","P2","B5","R10","P4","R1","P8","P2","P3","P8","P3","B5","B3","B3","B2","P8","R5","R3","R8","R3","R1","P8","R2","P3","B3","R3","P3","P3","R8","P8","B5","B4","R8"];function V(n){const t=n.eco??_[n.n-1],e=L.get(t);if(!e)throw new Error(`Missing ECO 2026 task for question ${n.n}`);return e}function tn(n){return a.map(t=>({...t,questions:n.filter(e=>V(e).id===t.id)}))}export{i as B,F as C,Y as D,J as E,$ as O,L as T,X as a,z as b,Z as c,nn as d,a as e,U as f,tn as m,V as t,G as v};
